window.HM_DATA.SHUOWEN = {"空":{"expl":"竅也。从穴工聲。","rad":"穴","fanqie":"苦紅切","vol":"07","duan":[{"e":"竅也。","n":"今俗語所謂孔也。天地之閒亦一孔耳。古者司空主土。尙書大傳曰。城郭不繕。溝池不修。水泉不修。水爲民害。責於地公。司馬彪曰。司空公一人。掌水土事。凡營城、起邑、浚溝洫、修墳防之事。則議其利、建其功。是則司空以治水土爲職。禹作司空。治水而後晉百揆也。治水者必通其瀆。故曰司空猶司孔也。"},{"e":"从穴。工聲。","n":"形聲包會意也。苦紅切。九部。"}]},"晖":{"expl":"光也。从日軍聲。","rad":"日","fanqie":"許歸切","vol":"07","duan":[{"e":"灮也。","n":"按光也二字當作日光氣也四字。篆體暉當作暈。周禮暈作煇。古文叚借字。眡𥛆掌十煇之法。以觀妖祥。辨吉凶。一曰𥛆。二曰象。三曰鑴。四曰監。五曰闇。六曰瞢。七曰彌。八曰敘。九曰隮。十曰想。鄭司農云。煇謂日光炁也。按日光氣謂日光捲結之氣。釋名曰。暈、捲也。氣在外捲結之也。日月皆然。孟康曰。暈、日旁氣也。篆體日在上。或移之在旁。此篆遂改爲暉。改其訓曰光。與火部之煇不別。葢淺者爲之。乃致鉉以暈爲新附篆矣。"},{"e":"从日。軍聲。","n":"軍者、圜圍也。此以形聲包會意。王問切。十三部。大徐許歸切。非。"}]},"伦":{"expl":"輩也。从人侖聲。一曰道也。","rad":"人","fanqie":"田屯切","vol":"08","duan":[{"e":"輩也。","n":"軍發車百兩爲輩。引伸之同類之次曰輩。鄭注曲禮、樂記曰。倫猶類也。注卽夕曰。比也。注中庸曰。猶比也。"},{"e":"从人。侖聲。","n":"力屯切。十三部。"}]},"父":{"expl":"矩也。家長率教者。从又舉杖。","rad":"又","fanqie":"扶雨切","vol":"03","duan":[{"e":"巨也。","n":"以曡韵釋之。"},{"e":"家長率敎者。","n":"率同䢦。先導也。經傳亦借父爲甫。"}]},"心":{"expl":"人心，土藏，在身之中。象形。博士說以爲火藏。凡心之屬皆从心。","rad":"心","fanqie":"息林切","vol":"10","duan":[{"e":"人心。土臧也。","n":"也字補。"},{"e":"在身之中象形。","n":"息林切。七部。"}]},"金":{"expl":"五色金也。黃爲之長。久薶不生衣，百鍊不輕，从革不違。西方之行。生於土，从土；左右注，象金在土中形；今聲。凡金之屬皆从金。","rad":"金","fanqie":"居音切","vol":"14","duan":[{"e":"五色金也。","n":"凡有五色。皆謂之金也。下文白金、靑金、赤金、黑金、合黃金爲五色。"},{"e":"黃爲之長。","n":"故獨得金名。"}]},"嵘":{"expl":"崝嶸也。从山榮聲。","rad":"山","fanqie":"戶萌切","vol":"09","duan":[{"e":"崝嶸也。从山。榮聲。","n":"戸萌切。十二部。亦作嵤。"}]},"秋":{"expl":"禾穀孰也。从禾，𤒅省聲。","rad":"禾","fanqie":"七由切","vol":"07","duan":[{"e":"禾穀孰也。","n":"其時萬物皆老。而莫貴於禾穀。故从禾。言禾復言穀者、晐百穀也。禮記曰。西方者秋。秋之爲言揫也。"},{"e":"从禾。𪚰省聲。","n":"七由切。三部。"}]},"晨":{"expl":"房星；爲民田時者。从晶辰聲。","rad":"晶","fanqie":"植鄰切","vol":"07","duan":[{"e":"房星。","n":"爾雅曰。天駟、房也。大辰、房心尾也。於天官爲東官蒼龍。"},{"e":"爲民田時者。","n":"周語曰。農祥䢅正。韋云。農祥、房星也。䢅正、謂立春之日䢅中於午也。農事之𠋫。故曰農祥。爾雅注曰。龍星明者以爲時𠋫。故曰大辰。"}]},"贾":{"expl":"賈市也。从貝襾聲。一曰坐賣售也。","rad":"貝","fanqie":"公戶切","vol":"06","duan":[{"e":"賈、","n":"此複舉字之未刪者。"},{"e":"市也。","n":"市、買賣所之也。因之凡買凡賣皆曰市。賈者、凡買賣之偁也。酒誥曰。遠服賈。漢石經論語曰。求善賈而賈諸。今論語作沽者、假借字也。引伸之凡賣者之所得、買者之所出、皆曰賈。俗又別其字作價。別其音入禡韵。古無是也。"}]},"无":{"expl":"亡也。从亾𣞤聲。","rad":"亾","fanqie":"武扶切","vol":"12","duan":[{"e":"亡也。","n":"凡所失者、所未有者皆如逃亡然也。此有無字之正體。而俗作無。無乃𣞤之隷變。𣞤之訓豐也。與無義正相反。然則隷變之時。昧於亡爲其義。𣞤爲其聲。有聲無義。殊爲乖繆。古有叚𣞤爲𣠮者。要不得云本無二字。漢隷多作𣠮可證也。或叚亡爲無者、其義同。其音則雙聲也。"},{"e":"从亾。𣞤聲。","n":"按不用莫聲而用𣞤聲者、形聲中有會意。凡物必自多而少而無。老子所謂多藏必厚亡也。武夫切。五部。古音武夫與莫胡二切不別。故無、模同音。其轉語則水經注云燕人謂無爲毛、楊子以曼爲無、今人謂無有爲𣳚有皆是也。"}]},"杭":{"expl":"扞也。从手亢聲。","rad":"手","fanqie":"苦浪切","vol":"12","duan":[{"e":"扞也。","n":"旣夕禮注曰。抗、禦也。左傳曰。以亢其讎。注云。亢猶當也。亢爲抗之叚借字。周禮。綱惡馬。注云。綱讀爲以亢其讎之亢。書亦或爲亢。亢、禦也。禁也。綱亦亢之、叚借字也。引申之義爲高抗。旣夕注曰。抗、舉也。"},{"e":"从手。亢聲。","n":"苦浪切。十部。"}]},"高":{"expl":"崇也。象臺觀高之形。从冂、口。與倉、舍同意。凡高之屬皆从高。","rad":"高","fanqie":"古牢切","vol":"05","duan":[{"e":"崇也。","n":"山部曰。崇、嵬高也。"},{"e":"象臺觀高之形。","n":"謂？也。"}]},"彭":{"expl":"鼓聲也。从壴彡聲。","rad":"壴","fanqie":"薄庚切","vol":"05","duan":[{"e":"𡔷聲也。","n":"詩之言𡔷聲者惟鼉𡔷逢逢。毛曰。逢逢、和也。逢逢埤蒼、廣雅作韸韸。高注淮南吕覽、郭注山海經引詩皆作韸韸。許無韸字。彭卽韸也。東陽合韵也。毛詩。出車彭彭。又四牡彭彭。又駟騵彭彭。又以車彭彭。凡言彭彭皆謂馬。卽鄭風駟？旁旁之異文。彭旁皆假借。其正字則馬部之騯也。言馬而假𡔷聲之字者。其壯盛相似也。齊風。行人彭彭。傳曰。多皃。亦盛意。"},{"e":"从壴。","n":"𡔷省。"}]},"澹":{"expl":"水搖也。从水詹聲。","rad":"水","fanqie":"徒濫切","vol":"11","duan":[{"e":"澹澹水繇皃也。","n":"東京賦注、高唐賦注引皆有澹澹字。皃字亦依東京賦注補。高唐賦曰。水澹澹而盤紆。東京賦曰。淥水澹澹。俗借爲淡泊字。繇當作搖。"}]},"薇":{"expl":"菜也。似藿。从艸微聲。","rad":"艸","fanqie":"無非切","vol":"01","duan":[{"e":"菜也。","n":"見毛傳。"},{"e":"佀藿。","n":"謂似豆葉也。陸璣詩疏曰。薇、山菜也。莖葉皆似小豆。蔓生。其味亦如小豆。藿可作羹。亦可生食。今官園種之。以供宗廟祭祀。項安世曰。薇、今之野豌豆也。蜀人謂之大巢菜。按今四川人掐豌豆媆梢食之。謂之豌豆顚顚。古之采於山者、野生者也。釋艸云垂水。薇之俗名耳。不當以生於水邊釋之。"}]},"渊":{"expl":"回水也。从水，象形。左右，岸也。中象水皃。","rad":"水","fanqie":"烏玄切","vol":"11","duan":[{"e":"回水也。","n":"顏回字子淵。"},{"e":"从水。象形。","n":"下文釋象形。"}]},"浩":{"expl":"澆也。从水告聲。《虞書》曰：“洪水浩浩。”","rad":"水","fanqie":"胡老切","vol":"11","duan":[{"e":"澆也。","n":"按澆當作沆。字之誤也。澆者、𣵽也.𣵽非浩義。沄浩沆同義。而又雙聲。故三篆相聯。"},{"e":"从水。告聲。","n":"胡老切。古音𡉈三部。"}]},"维":{"expl":"車蓋維也。从糸隹聲。","rad":"糸","fanqie":"以追切","vol":"13","duan":[{"e":"車葢維也。","n":"車葢之制、詳於考工記。而其維無考。許以此篆專系之車葢。葢必有所受矣。引申之、凡相系者曰維。韍維、綬維是也。管子曰。禮義廉恥。國之四維。"},{"e":"从糸。隹聲。","n":"以追切。十五部。"}]},"佳":{"expl":"善也。从人圭聲。","rad":"人","fanqie":"古膎切","vol":"08","duan":[{"e":"善也。","n":"廣韵曰。佳、善也。又曰。好也。又曰。大也。老子。佳兵者不祥。淮南說林訓曰。佳人不同體。美人不同面。而皆說於目。"},{"e":"从人。圭聲。","n":"古膎切。十六部。按唐人入於下平九麻。"}]},"悠":{"expl":"憂也。从心攸聲。","rad":"心","fanqie":"以周切","vol":"10","duan":[{"e":"𢝊也。","n":"釋訓曰。悠悠、洋洋、思也。小雅。悠悠我里。傳曰。悠悠、憂也。按此傳乃悠之本義。渭陽。悠悠我思。無傳。葢同釋訓。若黍離悠悠蒼天傳曰。悠悠、遠意。此謂悠同攸。攸同脩。古多叚攸爲脩。長也、遠也。"},{"e":"从心。攸聲。","n":"以周切。三部。"}]},"筠":{"expl":"竹皮也。从竹均聲。","rad":"竹","fanqie":"王春切","vol":"05","duan":[]},"台":{"expl":"觀，四方而高者。从至从之，从高省。與室屋同意。","rad":"至","fanqie":"徒哀切","vol":"12","duan":[{"e":"觀四方而高者也。","n":"釋名曰。觀、觀也。於上觀望也。觀不必四方。其四方獨出而高者、則謂之臺。大雅。經始靈臺。釋宮、毛傳曰。四方而高曰臺。傳意高而不四方者則謂之觀、謂之闕也。釋名。臺、持也。築土堅高能自勝持也。古臺讀同持。心曰靈臺。謂能持物。淮南子。其所居神者、臺𥳑以游大淸。注。臺、持也。又臺無所鑒、謂之狂生。注。臺、持也。此皆作臺自可通。或作古文握。古文握與臺形相似。"},{"e":"从至。从高省。與室屋同意。","n":"按臺不必有屋。李巡注爾雅曰。臺上有屋謂之謝。然則無屋者謂之臺。築高而已。云與室屋同意者、室屋篆下皆云从至者所止也。是其意也。"}]},"云":{"expl":"山川气也。从雨，云象雲回轉形。凡雲之屬皆从雲。","rad":"雲","fanqie":"王分切","vol":"11","duan":[{"e":"山川气也。","n":"天降時雨。山川出雲。"},{"e":"从雨。云象回轉之形。","n":"回上各本有雲字。今刪。古文衹作云。小篆加雨於上。遂爲半體會意、半體象形之字矣。云象回轉形、此釋下古文雲爲象形也。王分切。十三部。"}]},"崇":{"expl":"嵬高也。从山宗聲。","rad":"山","fanqie":"鉏弓切","vol":"09","duan":[{"e":"山大而高也。","n":"各本作巍高也三字。今正。大雅。崧高維嶽。釋山、毛傳皆曰。山大而高曰崧。孔子閒居引詩崧作嵩。釋名作山大而高曰嵩。崧嵩二形皆卽崇之異體。韋注國語云。古通用崇字。太平御覽及徐鉉皆引其語。詩序曰。崇丘、萬物得極其高大也。此崇之故訓也。河東賦。瞰帝唐之嵩高。眽隆周之大寧。嵩高卽崇高也。漢碑曰。如山如岳。嵩如不傾。謂崇而不傾也。中嶽、禹貢謂之外方。秦名大室。漢武帝始謂之崇高山。因以山下戸三百爲之奉邑。名曰崇高縣。武帝紀、郊祀志、地理志、封禪書可證。崇字地裏志作崈。體之小異耳。史、漢或崇嵩錯出。要無礙爲一字。惟後漢書靈帝紀。熹平五年復崇高山爲嵩高山。語大可疑。證以東觀紀。堂谿典請雨。因上言改之。名爲嵩高山。是則非復崇高爲嵩高。乃改崇高爲嵩高。葢其時六書之學不明。謂嵩與崇別而改之。沿至今日。尙仍其誤。李賢注云。前書武帝祠中嶽。改嵩高爲崇高。前書未嘗有此文。武帝改大室爲崇高。武帝以前但曰大室。不曰嵩高也。崇"},{"e":"从山。宗聲。","n":"鉏弓切。九部。此篆舊在岊篆之後。解云嵬高也。必轉寫之誤。今依玉篇移其次。依毛傳、釋名易其解。"}]},"南":{"expl":"艸木至南方，有枝任也。从𣎵𢆉聲。","rad":"𣎵","fanqie":"那含切","vol":"06","duan":[{"e":"艸木至南方有枝任也。","n":"此亦脫誤。當云南任也。與東動也一例。下乃云艸木至南方有枝任也、發明从𣎵之意。漢律曆志曰。大陽者南方。南任也。陽氣任養物。於時爲夏。云艸木至南方者、猶云艸木至夏也。有枝任者、謂夏時艸木畼楙丁壯、有所枝𠲱任載也。故从𣎵。按古南男二字相假借。"},{"e":"从𣎵。𢆉聲。","n":"𨙻含切。古音在七部。"}]},"夏":{"expl":"中國之人也。从夊从頁从𦥑。𦥑，兩手；夊，兩足也。","rad":"夊","fanqie":"胡雅切","vol":"05","duan":[{"e":"中國之人也。","n":"以別於北方狄、東北貉、南方蠻閩、西方羌、西南焦僥、東方夷也。夏、引伸之義爲大也。"},{"e":"从夊。从頁。从臼。臼、㒳手。夊、㒳足也。","n":"胡雅切。古音在五部。"}]},"瑾":{"expl":"瑾瑜，美玉也。从玉堇聲。","rad":"玉","fanqie":"居隱切","vol":"01","duan":[{"e":"瑾瑜、","n":"逗。"},{"e":"美玉也。","n":"左氏傳曰。瑾瑜匿瑕。山海經。黃帝乃取密山之玉榮而投之鍾山之陽。瑾瑜之玉爲良。王逸注九章云。瑾瑜、美玉也。"}]},"雪":{"expl":"凝雨，說物者。从雨彗聲。","rad":"雨","fanqie":"相絕切","vol":"11","duan":[{"e":"冰雨說物者也。","n":"冰各本作凝。今正。凝者、冰之俗也。釋名曰。雪、綏也。水下遇寒氣而凝。綏綏然下也。故許謂之冰雨。說今之悅字。物無不喜雪者。說與雪曡韵。"},{"e":"从雨。彗聲。","n":"相絕切。十五部。"}]},"邵":{"expl":"晉邑也。从邑召聲。","rad":"邑","fanqie":"寔照切","vol":"06","duan":[{"e":"晉邑也。","n":"左傳襄二十三年。齊矦伐衞。遂伐晉。入孟門。登大行。張武軍於熒庭。戍郫邵。杜曰。取晉邑而守之。杜不言郫邵二邑名。據許則當是二邑也。文六年。賈季召公子樂於陳。趙孟使殺諸郫。此單言郫也。後志。河東垣縣有邵亭。注引博物記。縣東九十里有郫邵之阨。趙孟殺公子樂於郫邵。豈張華所見左傳有異歟。按今山西絳州垣曲縣東有邵城。後魏之邵郡、後周之邵州皆此也。依許則經典獨此字從邑召。凡周召字作邵者俗也。後儒或謂垣曲邵城爲周召分陜之所。其說不經。"},{"e":"从邑。召聲。","n":"寔照切。二部。"}]},"汪":{"expl":"深廣也。从水王聲。一曰汪，池也。","rad":"水","fanqie":"烏光切","vol":"11","duan":[{"e":"深廣也。","n":"謂深而又廣也。後漢書。叔度汪汪若千頃陂。江賦。澄澹汪洸。晉語曰。汪是土也。韋云。汪、大貌。"},{"e":"从水。𡉚聲。","n":"俗作汪。烏光切。十部。"}]},"沐":{"expl":"濯髮也。从水木聲。","rad":"水","fanqie":"莫卜切","vol":"11","duan":[{"e":"濯髮也。","n":"引伸爲芟除之義。如管子云沐涂樹之枝。釋名云沐秃無上皃之稱。"},{"e":"从水。木聲。","n":"莫⺊切。三部。"}]},"尹":{"expl":"治也。从又、丿，握事者也。","rad":"又","fanqie":"余凖切","vol":"03","duan":[{"e":"治也。","n":"伊下曰。尹治天下。廣韵曰。正也。進也。誠也。"},{"e":"从又丿。","n":"句。"}]},"畜":{"expl":"田畜也。《淮南子》曰：“玄田爲畜。”","rad":"田","fanqie":"丑六切","vol":"13","duan":[{"e":"田畜也。","n":"田畜謂力田之蓄積也。貨殖列傳曰。富人爭奢侈。而任氏獨折節爲儉。力田畜。田畜人爭取賤賈。任氏獨取貴善。非田畜所出弗衣食。艸部曰。蓄、積也。畜與蓄義略同。畜从田。其源也。蓄从艸。其委也。俗用畜爲六嘼字。古叚爲好字。如說苑尹逸對成王曰。民善之則畜也。不善則讎也。晏子對景公曰。畜君何尤。畜君者、好君也。謂畜卽好之同音叚借也。"},{"e":"淮南王曰。玄田爲畜。","n":"王大徐作子。此如引楚莊王止戈爲武、說會意也。玄田猶畇畇原隰也。丑六切。亦許六切。三部。"}]},"贺":{"expl":"以禮相奉慶也。从貝加聲。","rad":"貝","fanqie":"胡箇切","vol":"06","duan":[{"e":"㠯禮物相奉慶也。","n":"物字依韵會、玉篇補。相奉慶、玉篇作相慶加、爲長。心部曰。慶行賀人也。是慶與賀二字互訓。賀之言加也。猶贈之言增也。古假賀爲嘉。覲禮。余一人嘉之。今文嘉作賀是也。廣韵曰。賀、擔也。勞也。此謂或假賀爲儋何字也。儋何、俗作擔荷。"},{"e":"从貝。加聲。","n":"胡箇切。十七部。"}]},"楷":{"expl":"木也。孔子冢蓋樹之者。从木皆聲。","rad":"木","fanqie":"苦駭切","vol":"06","duan":[{"e":"楷木也。孔子冢葢樹之者。","n":"皇覽云。冢塋中樹以百數。皆異種。傳言弟子各持其方樹來穜之。按楷亦方樹之一也。儒行曰。今世行之。後世以爲楷。楷、法式也。楷之言稽。我稽古、而後世又於此焉稽也。"},{"e":"从木。皆聲。","n":"苦駭切。十五部。以下言木名。故先之以孔冢所樹。"}]},"诸":{"expl":"辯也。从言者聲。","rad":"言","fanqie":"章魚切","vol":"03","duan":[{"e":"辯也。","n":"辯當作辨。判也。按辨下奪䛐字。諸不訓辨。辨之䛐也。䛐者、意內而言外也。白部曰。者、别事䛐也。諸與者音義皆同。釋魚。前弇諸果。後弇諸獵。諸卽者。郊特牲。或諸遠人乎。亦作或者遠人乎。凡舉其一。則其餘謂之諸以别之。因之訓諸爲衆。或訓爲之。或訓爲之於。則於雙聲曡韵求之。"},{"e":"从言。者聲。","n":"此以聲苞意。章魚切。五部。"}]},"冯":{"expl":"馬行疾也。从馬冫聲。","rad":"馬","fanqie":"房戎切","vol":"10","duan":[{"e":"馬行疾也。从馬仌聲。","n":"皮冰切。六部。按馬行疾馮馮然、此馮之本義也。展轉他用而馮之本義廢矣。馮者、馬蹏箸地堅實之皃。因之引伸其義爲盛也、大也、滿也、懣也。如左傳之馮怒、離騷之馮心、以及天問之馮翼惟象、淮南書之馮馮翼翼、地理志之左馮翊皆謂充盛。皆畐字之合音假借。畐者、滿也。或叚爲凭字。凡經傳云馮依、其字皆當作凭。或叚爲淜字。如易、詩、論語之馮河皆當作淜也。俗作憑。非是。"}]},"龙":{"expl":"鱗蟲之長。能幽，能明，能細，能巨，能短，能長；春分而登天，秋分而潛淵。从肉，飛之形，童省聲。凡龍之屬皆从龍。","rad":"龍","fanqie":"力鍾切","vol":"11","duan":[{"e":"𩼩蟲之長。能幽能朙。能細能巨。能短能長。","n":"四句一韵。"},{"e":"春分而登天。秋分而潛淵。","n":"二句一韵。毛詩蓼蕭傳曰。龍、寵也。謂龍卽寵之叚借也。勺傳曰。龍、和也。長發同。謂龍爲邕和之叚借字也。"}]},"婉":{"expl":"順也。从女宛聲。《春秋傳》曰：“太子痤婉。”","rad":"女","fanqie":"於阮切","vol":"12","duan":[{"e":"順也。","n":"鄭風傳曰。婉然美也。齊風傳曰。婉、好眉目也。"},{"e":"从女。宛聲。","n":"於阮切。十四部。"}]},"钟":{"expl":"酒器也。从金重聲。","rad":"金","fanqie":"職容切","vol":"14","duan":[{"e":"酒器也。","n":"古者此器葢用以宁酒。故大其下、小其頸。自鍾傾之而入於尊。自尊勺之而入於觶。故量之大者亦曰鍾。引申之義爲鍾聚。"},{"e":"从金。重聲。","n":"職容切。九部。"}]},"叶":{"expl":"艸木之葉也。从艸枼聲。","rad":"艸","fanqie":"与涉切","vol":"01","duan":[{"e":"艸木之葉也。","n":"凡物之薄者、皆得以葉名。"},{"e":"从艸。枼聲。","n":"與涉切。古音在八部。"}]},"闻":{"expl":"知聞也。从耳門聲。","rad":"耳","fanqie":"無分切","vol":"12","duan":[{"e":"知聲也。","n":"往曰聽。來曰聞。大學曰。心不在焉。聽而不聞。引申之爲令聞廣譽。"},{"e":"从耳。門聲。","n":"無分切。十二部。"}]},"辰":{"expl":"震也。三月，陽气動，靁電振，民農時也。物皆生，从乙、匕，象芒達；厂，聲也。辰，房星，天時也。从二，二，古文上字。凡辰之屬皆从辰。","rad":"辰","fanqie":"植鄰切","vol":"14","duan":[{"e":"震也。三月昜气動。靁電振。民農時也。物皆生。","n":"震振古通用。振、奮也。律書曰。辰者、言萬物之蜄也。律曆志曰。振美於辰。釋名曰。辰、伸也。物皆伸舒而出也。季春之月。生氣方盛。陽氣發泄。句者畢出。萌者盡達。二月靁發聲。始電至。三月而大振動。豳風曰。四之日舉止。故曰民農時。"},{"e":"从乙匕。","n":"匕呼跨切。變也。此合二字會意。乙象春艸木冤曲而出。陰氣尙強。其山乙乙。至是月陽氣大盛。乙乙難出者始變化矣。"}]},"诚":{"expl":"信也。从言成聲。","rad":"言","fanqie":"氏征切","vol":"03","duan":[{"e":"信也。从言。成聲。","n":"氏征切。十一部。"}]},"杰":{"expl":"傲也。从人桀聲。","rad":"人","fanqie":"渠列切","vol":"08","duan":[{"e":"埶也。","n":"以疊韵爲訓。埶本穜埶字。引伸爲勢力字。傑者言其勢傑然也。衞風毛傳曰。桀、特立也。"},{"e":"材過萬人也。","n":"辨名記、尹文子、高誘、趙岐、王逸說同。以上七字大徐作傲也二字。非古義。且何不與傲篆相屬而廁之俊篆下乎。二傳相屬則義相近。全書之例也。"}]},"冰":{"expl":"水堅也。从仌从水。","rad":"仌","fanqie":"魚陵切","vol":"11","duan":[{"e":"水堅也。","n":"易象傳。初六履霜。陰始凝也。馴致其道。至堅冰也。古本當作陰始冰也。至堅仌也。釋器。冰脂也。孫本冰作凝。按此可證詩膚如凝脂、本作冰脂。以冰代仌、乃別製凝字。經典凡凝字皆冰之變也。"},{"e":"从水仌。","n":"會意。魚陵切。六部。"}]},"陆":{"expl":"高平地。从𨸏从坴，坴亦聲。","rad":"𨸏","fanqie":"力竹切","vol":"14","duan":[{"e":"高平地。","n":"釋地、毛傳皆曰。高平曰陸。"},{"e":"从𨸏。坴聲。","n":"土部坴下曰。土塊坴坴也。然則陸从坴者、謂其有土無石也。大徐作从𨸏从坴、坴亦聲。力竹切。三部。"}]},"军":{"expl":"圜圍也。四千人爲軍。从車，从包省。軍，兵車也。","rad":"車","fanqie":"舉云切","vol":"14","duan":[{"e":"圜圍也。","n":"於字形得圜義。於字音得圍義。凡渾䡣煇等軍聲之字皆兼取其義。"},{"e":"四千人爲軍。","n":"王氏鳴盛說此句必譌。按唐釋玄應引字林四千人爲軍。是呂忱之誤也。許書當作萬有二千五百人爲軍。見周禮大司馬職。旅篆下云。軍之五百人爲旅。師篆下云。二千五百人爲師。旣皆偁之、則此必偁無可疑者。百人爲卒。卄有五人爲㒳。不偁者以其制於字義相遠耳。若万二千五百人以爲圜圍。乃此篆之所由製。"}]},"子":{"expl":"十一月，陽气動，萬物滋，人以爲偁。象形。凡子之屬皆从子。(李陽冰曰：“子在襁緥中，足併也。”)","rad":"子","fanqie":"卽里切","vol":"14","duan":[{"e":"十一月昜气動。萬物滋。","n":"律書。子者、滋也。言萬物滋於下也。律曆志曰。孶萌於子。"},{"e":"人㠯爲偁。","n":"人各本譌入。今正。此與以朋爲朋攩、以韋爲皮韋、以烏爲烏呼、以來爲行來、以西爲東西一例。凡言以爲者、皆許君發明六書叚借之法。子本陽气動萬物滋之偁。萬物莫靈於人。故因叚借以爲人之偁。"}]},"汶":{"expl":"水。出琅邪朱虛東泰山，東入濰。从水文聲。桑欽說：汶水出泰山萊蕪，西南入泲。","rad":"水","fanqie":"亡運切","vol":"11","duan":[{"e":"汶水。出琅邪朱虚東泰山。東入濰","n":"琅邪郡朱虛、見前志。後志屬北海國。今山東靑州府臨胊縣東六十里有朱虛故城。前志朱虛下云。東泰山、汶水所出。東至安丘入維。水經曰。汶水、出朱虛縣泰山。北過其縣東。又北過淳于縣西。又東北入於濰。謂之東汶水。以別於禹貢汶水也。按東泰山卽封禪書黃帝封東泰山、今沂山是也。今東汶河源出臨胊縣南沂山東北谷。東流近穆陵關。折東北流數十里。折東流百五十里。至安邱縣西南境。折東北流經縣城西北。又東流數十里與濰水會。"},{"e":"从水。文聲。","n":"亡運切。十三部。按二汶水在齊。漢人崏山崏江字作汶山汶江。以古音同讀如文之故。謂之假借可也。考工記。貉踰汶則死。淮南子同。鄭云。汶水在魯北。酈注以入汶水篇。考工記多齊語、則謂入？之汶無疑也。殷敬順剏爲異說。殊非是。"}]},"津":{"expl":"水渡也。从水𦘔聲。","rad":"水","fanqie":"將鄰切","vol":"11","duan":[{"e":"水渡也。","n":"商書微子曰。若涉大水其無津。俗本妄增涯字。按經傳多假借津爲𧗃潤字。周禮其民黑而津是。"},{"e":"从水。𦘔聲。","n":"將鄰切。十二部。隸省作津。"}]},"岳":{"expl":"東，岱；南，靃；西，華；北，恆；中，泰室。王者之所以巡狩所至。从山獄聲。","rad":"山","fanqie":"五角切","vol":"09","duan":[{"e":"東岱、","n":"見下。"},{"e":"南靃、","n":"南靃者、衡山也。在今湖南衡州府衡山縣西北。風俗通曰。衡山一名霍山。爾雅釋山曰。霍山爲南嶽。尙書大傳、白虎通皆舉霍山。毛傳則曰。南嶽、衡。許宗毛者也。曰南霍、正皆謂今湖南之衡山。卽漢地理志長沙國湘南縣東南之禹貢衡山也。封禪書。漢武帝元封四年。巡南郡。至江陵而東。登禮灊之天柱山。號曰南嶽。此郭景純所謂武帝以衡山遼曠。移其神於天柱者。葢自是天柱始有霍山之名。而衡山不曰霍山矣。許言霍者、從其朔偁也。天柱山者、今安徽六安州霍山縣南之霍山是也。"}]},"家":{"expl":"居也。从宀，豭省聲。","rad":"宀","fanqie":"古牙切","vol":"07","duan":[{"e":"凥也。","n":"凥各本作居。今正。凥、處也。處、止也。釋宫。牖戸之閒謂之扆。其內謂之家。引伸之天子諸侯曰國。大夫曰家。凡古曰家人者、猶今曰人家也。家人字見哀四年左傳、夏小正傳及史記、漢書。家凥曡韵。"},{"e":"从宀。豭省聲。","n":"古牙切。古音在五部。按此字爲一大疑案。豭省聲讀家。學者但見从豕而已。从豕之字多矣。安見其爲豭省耶。何以不云叚聲。而紆回至此耶。竊謂此篆本義乃豕之凥也。引申叚借以爲人之凥。字義之轉移多如此。牢、牛之凥也。引伸爲所以拘罪之𨻼牢。庸有異乎。豢豕之生子冣多。故人凥聚處借用其字。久而忘其字之本義。使引伸之義得冒據之。葢自古而然。許書之作也。盡正其失。而猶未免此。且曲爲之說。是千慮之一失也。家篆當入豕部。"}]},"正":{"expl":"是也。从止，一以止。凡正之屬皆从正。","rad":"正","fanqie":"之盛切","vol":"02","duan":[{"e":"是也。从一。（句）一㠯止。","n":"江沅曰。一所㠯止之也。如乍之止亡、毋之止姦。皆以一止之。之盛切。十一部。"},{"e":"古文正.。从𠄞。𠄞古文上字。","n":"此亦同䇂示辰龍童音章皆从𠄞。"}]},"昕":{"expl":"旦明，日將出也。从日斤聲。讀若希。","rad":"日","fanqie":"許斤切","vol":"07","duan":[{"e":"且朙也。","n":"小徐本作旦也。明也。韵會作旦明也。今正爲且明。文王世子。大昕。鄭云。早昧爽也。是昕卽䢅而未旦也。士昏禮記曰。凡行事必用昏昕。齊風。東方未晞。顚倒裳衣。傳曰。晞、明之始升。按蒹葭、湛露傳皆云。晞、乾也。此云明之始升則當作昕無疑。昕與晞各形各義。而昕讀同希。因誤爲晞耳。"},{"e":"日將出也。","n":"按此亦言且明而不次諸晢篆之前者。正謂昧爽於旦猶遠。昕於旦僅一閒耳。故毛云明之始升。許先列晢曉篆後而以昕足之。"}]},"博":{"expl":"大通也。从十从尃。尃，布也。","rad":"十","fanqie":"補各切","vol":"03","duan":[{"e":"大通也。","n":"凡取於人易爲力曰博。陳風鄭箋。交博好也。"},{"e":"从十博。","n":"會意。"}]},"妄":{"expl":"亂也。从女亡聲。","rad":"女","fanqie":"巫放切","vol":"12","duan":[{"e":"亂也。从女。亡聲。","n":"巫放切。十部。"}]},"曾":{"expl":"詞之舒也。从八从曰，𡆧聲。","rad":"八","fanqie":"昨稜切","vol":"02","duan":[{"e":"䛐之舒也。","n":"曰部曰。朁曾也。詩朁不畏明胡朁莫懲。毛鄭皆曰。朁、曾也。按曾之言乃也。詩曾是不意、曾是在位、曾是在服、曾是莫聽、論語曾是以爲孝乎、曾謂泰山不如林放乎、孟子爾何曾比予於管仲、皆訓爲乃則合語氣。趙注孟子曰。何曾猶何乃也。是也。是以朁訓爲曾。朁不畏明者、乃不畏明也。皇侃論語疏曰。曾猶嘗也。嘗是以爲孝乎。絶非語氣、葢曾字古訓乃。子登切。後世用爲曾經之義。讀才登切。此今義今音。非古義古音也。至如曾祖、曾孫、取增益層絫之意。則曾層皆可讀矣。"},{"e":"从八。从曰。","n":"从八者亦象氣之分散。"}]},"大":{"expl":"天大，地大，人亦大。故大象人形。古文大(他達切)也。凡大之屬皆从大。","rad":"大","fanqie":"徒蓋切","vol":"10","duan":[{"e":"天大。地大。人亦大焉。","n":"依韵會訂。"},{"e":"象人形。","n":"老子曰。道大。天大。地大。人亦大。人法地。地法天。天法道。按天之文从一大。則先造大字也。<人><儿>之文但象臂脛。大文則首手足皆具。而可以參天地。是爲大。徒葢切。十五部。"}]},"林":{"expl":"平土有叢木曰林。从二木。凡林之屬皆从林。","rad":"林","fanqie":"力尋切","vol":"06","duan":[{"e":"平土有叢木曰林。","n":"周禮林衡注曰。竹木生平地曰林。小雅依彼平林傳曰。平林、林木之在平地者也。？部曰。野外謂之林。引伸之義也。釋詁、毛傳皆曰。林、君也。假借之義也。"},{"e":"從二木。","n":"力尋切。七部。"}]},"新":{"expl":"取木也。从斤新聲。","rad":"斤","fanqie":"息鄰切","vol":"14","duan":[{"e":"取木也。","n":"取木者、新之本義。引申之爲凡始基之偁。采𦬊傳曰。田一歲曰葘。二歲曰新田。其一耑也。"},{"e":"从斤。𣓀聲。","n":"當作从斤木。辛聲。非從？聲也。息鄰切。十二部。"}]},"夹":{"expl":"持也。从大俠二人。","rad":"大","fanqie":"古狎切","vol":"10","duan":[{"e":"持也。","n":"持者、握也。握者、搤也。搤者、捉也。捉物必以兩手。故凡持曰㚒。左傳曰。㚒輔成王。古多叚俠爲㚒。公羊注曰。滕薛俠轂。"},{"e":"从大㚒二人。","n":"㚒各本作俠。俠者、俜也。非其義。今正㚒者、盜竊褱物也。从亦、有所持。㚒褱物。故从二入。夾持人、故从二人。大者、人也。一人而二人居其亦。猶一人二亦閒褱物也。故曰从大㚒二人。古狎切。八部。"}]},"沛":{"expl":"水。出遼東番汗塞外，西南入海。从水巿聲。","rad":"水","fanqie":"普蓋切","vol":"11","duan":[{"e":"沛水。出遼東番汗塞外。西南入海。","n":"番音盤。汗音寒。遼東郡番汗。二志同。今奉天府遼陽州、漢遼東郡治也。番汗未聞。前志番汗下曰。沛水出塞外。西南入海。沛水亦未聞。"},{"e":"从水。𣎳聲。","n":"普葢切。十五部。今字爲顚沛。跋之假借也。大雅蕩傳曰沛、拔也是也。拔當作跋。又本部渿下云沛之也、卽孟子沛然莫之能禦意。葢勃然之假借也。"}]},"思":{"expl":"容也。从心囟聲。凡思之屬皆从思。","rad":"思","fanqie":"息兹切","vol":"10","duan":[{"e":"䜭也。","n":"䜭也各本作容也。或以伏生尙書思心曰容說之。今正。皃曰恭、言曰從、視曰明、聽曰聰、思心曰容、謂五者之德。非可以恭釋皃、以從釋言、以明聰釋視聽也。谷部曰。䜭者、深通川也。引䜭畎澮歫川。引申之、凡深通皆曰䜭。思與䜭雙聲。此亦門捫也。戸護也、髮拔也之例。謂之思者、以其能深通也。至若尙書大傳次五事曰思心。思心之不容。是謂不聖。劉向、董仲舒、班固皆以寬釋容。與古文尙書作五曰思、思曰䜭爲異本。詳子所述尙書𢰅異。"},{"e":"从心。从𦥓。","n":"各本作𦥓聲。今依韵會訂。韵會曰。自𦥓至心如絲相貫不絕也。然則會意非形聲。細以𦥓爲聲。固非之咍部字也。息茲切。一部。"}]},"淳":{"expl":"渌也。从水𦎫聲。","rad":"水","fanqie":"常倫切","vol":"11","duan":[{"e":"淥也。","n":"上文曰。淥、或漉字。似？淋二篆宜類廁。恐轉寫者亂之也。內則、考工記注皆曰。淳、沃也。按㡆氏而沃之。卽上文之渥淳其帛也。內則淳熬、淳模之名。因沃之以膏也。然則許云淥也、謂淥之後一義。"},{"e":"从水。𦎧聲。","n":"常倫切。按當依經典釋文之純反。常倫乃不澆之訓。純醇二字之假借也。假借行而本義廢矣。十三部。"}]},"炎":{"expl":"火光上也。从重火。凡炎之屬皆从炎。","rad":"炎","fanqie":"于廉切","vol":"10","duan":[{"e":"火光上也。","n":"洪範曰。火曰炎上。其本義也。雲漢傳曰。炎炎、熱氣也。大田傳曰。炎、火盛陽也。皆引申之義也。"},{"e":"从重火。","n":"會意。于廉切。八部。"}]},"同":{"expl":"合會也。从𠔼从口。","rad":"𠔼","fanqie":"徒紅切","vol":"07","duan":[{"e":"合會也。从𠔼口。","n":"口皆在所覆之下。是同之意也。徒紅切。九部。"}]},"淼":{"expl":"大水也。从三水。或作渺。","rad":"水","fanqie":"亡沼切","vol":"11","duan":[]},"壮":{"expl":"大也。从士爿聲。","rad":"士","fanqie":"側亮切","vol":"01","duan":[{"e":"大也。","n":"方言曰。凡人之大謂之奘。或謂之壯。尋說文之例。當云大士也。故下云从士。此葢淺人𠜂士字。"},{"e":"从士。爿聲。","n":"側亮切。十部。"}]},"涛":{"expl":"大波也。从水壽聲。","rad":"水","fanqie":"徒刀切","vol":"11","duan":[]},"屠":{"expl":"刳也。从尸者聲。","rad":"尸","fanqie":"同都切","vol":"08","duan":[{"e":"刳也。","n":"刳、判也。"},{"e":"从尸。者聲。","n":"同都切。五部。"}]},"淇":{"expl":"水。出河内共北山，東入河。或曰出隆慮西山。从水其聲。","rad":"水","fanqie":"渠之切","vol":"11","duan":[{"e":"淇水。出河內𠔏北山。東入河。","n":"韵會引作東至黎陽入河。此用漢書增三字也。說文之例。舉所出之郡縣。不舉入河入江之郡縣。所出之地不變者多。下流古今多變。故略之也。河內郡𠔏、二志同。𠔏音恭。今河南衞輝府輝縣治、古𠔏城也。前志𠔏下曰。北山、淇水所出。東至黎陽入河。北山、今輝縣西北蘇門山。其別阜曰𠔏山是也。詩曰。毖彼泉水。亦流於淇。又曰。泉源在左。淇水在右。泉謂淇之源也。今淇水自彰德府林縣流入衞輝府淇縣境、入衞河而入海。與古入河者迥異。"},{"e":"或曰出隆慮西山。","n":"隆慮、漢諱殤帝改曰林慮。此不改者、書成於和帝永元十二年已前也。前志。河內郡隆慮。後志作林慮。慮音閭。今河南彰德府林縣是其地。西山者、今林縣西北二十五里隆慮山是也。水經曰。淇水出河內隆慮縣西大號山。東北入於海。山海經注亦曰今淇水出汲郡隆慮縣大號山。東過河內縣南爲白溝。"}]},"雕":{"expl":"鷻也。从隹周聲。","rad":"隹","fanqie":"都僚切","vol":"04","duan":[{"e":"鷻也。","n":"鳥部曰。鷻、雕也。假借爲琱琢、凋零字。"},{"e":"从隹。周聲。","n":"都僚切。二部。古音在三部。考工記故書雕或爲舟。"}]},"覃":{"expl":"長味也。从𣆪，鹹省聲。《詩》曰：“實覃實吁。”","rad":"㫗","fanqie":"徒含切","vol":"05","duan":[{"e":"長味也。","n":"此與酉部醰音同義近。醰以覃會意也。引伸之凡長皆曰覃。葛覃傳曰。覃、延也。凡言覃及、覃思義皆同。經典葛覃字亦假蕈爲之。"},{"e":"从𣆪。鹹省聲。","n":"當作鹹省、鹹亦聲。以从鹹故知字本義爲味長也。徒含切。古音在七部。"}]},"澜":{"expl":"大波爲瀾。从水闌聲。","rad":"水","fanqie":"洛干切","vol":"11","duan":[{"e":"大波爲瀾。","n":"魏風。河水淸且漣猗。釋水引作灡、云大波爲灡。毛傳云。風行水成文曰漣。按傳下文云。淪、小風水成文。則瀾爲大可知。與爾雅無二義也。凡瀾漫當作此瀾字。"},{"e":"从水。闌聲。","n":"洛干切。十四部。"}]},"徐":{"expl":"安行也。从彳余聲。","rad":"彳","fanqie":"似魚切","vol":"02","duan":[{"e":"安行也。从彳。余聲。","n":"似魚切。五部。"}]},"仲":{"expl":"中也。从人从中，中亦聲。","rad":"人","fanqie":"直衆切","vol":"08","duan":[{"e":"中也。","n":"白虎通同。伯仲叔季爲長少之次。伯仲見於此。子部曰。季、少偁也。叔則少之假借字也。古者幼名、冠字。冠字者、爲之且字也。且字也者、若尼甫嘉甫是也。五十以伯仲。乃偁伯某甫、仲某甫。以伯仲而後成字。伯仲之下一字爲且字。且者、薦也。爲伯仲之薦也。伯仲生而已定。故士冠禮字辭曰。伯某甫。雖定此字。而五十以前但偁某甫也。女子筓而字。則曰伯姬、曰仲姬。毛傳於大明曰。仲、中女也。於燕燕曰。仲、字也。皆言婦人也。二傳其實一也。古中仲二字互通。"},{"e":"从人中。中亦聲。","n":"直衆切。九部。"}]},"丘":{"expl":"土之高也，非人所爲也。从北从一。一，地也，人居在丘南，故从北。中邦之居，在崐崘東南。一曰四方高，中央下爲丘。象形。凡丘之屬皆从丘。(今隷變作丘。)","rad":"丘","fanqie":"去鳩切","vol":"08","duan":[{"e":"土之高也。","n":"大司徒注曰。土高曰丘。"},{"e":"非人所爲也。","n":"釋丘曰。非人爲之丘。謂非人力所爲也。"}]},"唐":{"expl":"大言也。从口庚聲。","rad":"口","fanqie":"徒郎切","vol":"02","duan":[{"e":"大言也。","n":"引伸爲大也。如說尙書者云。唐之爲言蕩蕩也。見論衡。又爲空也。如梵書云。福不唐捐。凡陂塘字古皆作唐。取虚而多受之意。𨸏部曰。隄、唐也。"},{"e":"从口。庚聲。","n":"徒郎切。十部。"}]},"胡":{"expl":"牛𩔞垂也。从肉古聲。","rad":"肉","fanqie":"戶孤切","vol":"04","duan":[{"e":"牛𩔞𠂹也。","n":"玄應、司馬貞引皆作牛領。按此言？以包頸也。？、頤也。牛自頤至頸下垂肥者也。引伸之凡物皆曰胡。如老狼有胡、鴺胡、龍垂胡䫇是也。胡與矦音轉冣近。故周禮立當前矦注曰。車轅前胡下垂柱地者。經傳胡矦遐皆訓何。士冠禮。永受胡福。鄭曰。胡猶遐也。毛傳。胡、壽也。謚法。彌年壽考曰胡。𠈃民耆艾曰胡。皆謂壽命遐遠。"},{"e":"从肉。古聲。","n":"戸孤切。五部。"}]},"蒋":{"expl":"苽蔣也。从艸將聲。","rad":"艸","fanqie":"子良切","vol":"01","duan":[{"e":"𤓰也。","n":"各本作𤓰蔣也。此蔣𤓰也之誤倒耳。今依御覽正。蜀都賦曰。攢蔣叢蒲。"},{"e":"从艸。將聲。","n":"子良切。十部。"}]},"燕":{"expl":"玄鳥也。籋口，布翄，枝尾。象形。凡燕之屬皆从燕。","rad":"燕","fanqie":"於甸切","vol":"11","duan":[{"e":"燕燕、玄鳥也。","n":"各本無燕燕二字。今補。𠃉下曰。燕燕也。齊魯謂之𠃉。隹部巂下曰。巂周者、燕也。邶風傳曰。燕燕、𠃉也。商頌傳曰。玄鳥、𠃉也。釋鳥曰。巂周、燕燕、𠃉也。古多叚燕爲宴安、宴享。"},{"e":"籋口。","n":"故以廿像之。"}]},"宣":{"expl":"天子宣室也。从宀𠄢聲。","rad":"宀","fanqie":"須緣切","vol":"07","duan":[{"e":"天子宣室也。","n":"葢謂大室。如璧大謂之瑄也。賈誼傳。孝文受釐坐宣室。蘇林曰。宣室、未央前正室也。天子宣室。葢禮家相傳古語。引伸爲布也。明也。徧也。通也。緩也。散也。"},{"e":"从宀。𠄢聲。","n":"須緣切。十四部。"}]},"有":{"expl":"不宜有也。《春秋傳》曰：“日月有食之。”从月又聲。凡有之屬皆从有。","rad":"有","fanqie":"云九切","vol":"07","duan":[{"e":"不宜有也。","n":"謂本是不當有而有之偁。引伸遂爲凡有之偁。凡春秋書有者、皆有字之本義也。"},{"e":"春秋傳曰。日月有食之。从月。","n":"日下之月、衍字也。此引經釋不宜有之恉。亦卽釋从月之意也。日不當見食也。而有食之者。孰食之。月食之也。月食之。故字从月。公羊傳注曰。不言月食之者。其形不可得而覩也。故疑言曰有食之。引孔子曰。多聞闕疑。愼言其餘。則寡尤。"}]},"朱":{"expl":"赤心木。松柏屬。从木，一在其中。","rad":"木","fanqie":"章俱切","vol":"06","duan":[{"e":"赤心木。松柏屬。","n":"朱本木名。引伸假借爲純赤之字。糸部曰。絑、純赤也。是其本字也。"},{"e":"從木。一在其中。","n":"赤心不可像。故以一識之。若本𠅅（末）非不可像者。於此知今本之非也。章俱切。古音𡉈四部。又按此字解云赤心木。松柏屬。當廁於松樠檜樅柏之処。今本失其舊次。本柢根株𠅅（末）五文一貫。不當中骾以他物。葢淺人類居之。以傳會其一𡉈上、一𡉈中、一𡉈下之說耳。"}]},"雨":{"expl":"水从雲下也。一象天，冂象雲，水霝其閒也。凡雨之屬皆从雨。","rad":"雨","fanqie":"王矩切","vol":"11","duan":[{"e":"水從雲下也。","n":"引申之凡自上而下者偁雨。"},{"e":"一象天。冂象雲。水霝其閒也。","n":"氺者、水字也。王矩切。五部。"}]},"叔":{"expl":"拾也。从又尗聲。汝南名收芌爲叔。","rad":"又","fanqie":"式竹切","vol":"03","duan":[{"e":"拾也。","n":"豳風。九月叔苴。毛曰。叔拾也。按釋名。仲父之弟曰叔父。叔、少也。於其雙聲曡韵假借之。假借旣久。而叔之本義鮮知之者。惟見於毛詩而已。"},{"e":"从又。","n":"於此知拾爲本義也。"}]},"狐":{"expl":"䄏獸也。鬼所乘之。有三徳：其色中和，小前大後，死則丘首。从犬瓜聲。","rad":"犬","fanqie":"戶吳切","vol":"10","duan":[{"e":"䄏獸也。鬼所乘之。","n":"爾雅音義無之字。"},{"e":"有三德。其色中和。小歬大後。","n":"廣韵作豐後。"}]},"栩":{"expl":"柔也。从木羽聲。其皁，一曰様。","rad":"木","fanqie":"況羽切","vol":"06","duan":[{"e":"栩𣏗也。","n":"見唐風毛傳。陸機曰。栩、今柞櫟也。徐州人謂櫟爲杼。或謂之爲栩。按毛傳、說文皆栩𣏗樣爲一木。櫟下但云木也。不云卽栩也。然則陸機專據徐州語言合之耳。"},{"e":"從木。羽聲。","n":"況羽切。五部。"}]},"容":{"expl":"盛也。从宀、谷。","rad":"宀","fanqie":"余封切","vol":"07","duan":[{"e":"盛也。","n":"今字叚借爲頌皃之頌。"},{"e":"从宀。谷聲。","n":"此依小徐本。谷古音讀如欲。以雙聲？聲也。鉉本作从宀谷。云屋與谷皆所以盛受也。亦通。余封切。九部。"}]},"孤":{"expl":"無父也。从子瓜聲。","rad":"子","fanqie":"古乎切","vol":"14","duan":[{"e":"無父也。","n":"孟子曰。幼而無父曰孤。引申之、凡單獨皆曰孤。弧則不相酬應。故背恩者曰孤負。孤則人輕賤之。故鄭注儀禮曰。不以己尊孤人也。"},{"e":"从子。瓜聲。","n":"古乎切。五部。"}]},"门":{"expl":"聞也。从二戶。象形。凡門之屬皆从門。","rad":"門","fanqie":"莫奔切","vol":"12","duan":[{"e":"聞也。","n":"以㬪韵爲訓。聞者、謂外可聞於內。內可聞於外也。"},{"e":"从二戶。象形。","n":"此如鬥从二丮。不必有反丮字也。莫奔切。十三部。"}]},"邹":{"expl":"魯縣，古邾國，帝顓頊之後所封。从邑芻聲。","rad":"邑","fanqie":"側鳩切","vol":"06","duan":[{"e":"魯縣。古邾婁國。帝顓頊之後所封。","n":"魯國騶、二志同。二志作騶、許作鄒者。葢許本作魯騶縣。如今汝南新息、今南陽穰縣之比。淺者乃刪去騶字耳。周時或云鄒、或云邾婁者。語言緩急之殊也。周時作鄒、漢時作騶者。古今字之異也。邾婁各本無婁。今依韵會所據正。左、榖作邾。公羊、檀弓作邾婁。婁如字。邾又夷也。邾婁之合聲爲鄒。夷語也。國語、孟子作鄒。三者鄒爲正。邾則省文。故邾篆下不言春秋邾國。此必依公羊作邾婁國也。漢時縣名作騶。如韓勑碑陰騶韋仲卿足證。鄭語曰。曹姓鄒莒。韋云。陸終第五子曰安。爲曹姓。封於鄒。杜諩云。邾、曹姓。顓頊之後。有六終。產六子。其弟五子曰安。邾卽安之後也。周武王封其苗裔俠爲附庸。居邾。前志曰。騶故邾國。曹姓。二十九世爲楚所滅。按左傳顓項氏有子曰黎爲祝融。祝融之後八姓。妘、曹其二也。然則上文鄶祝融之後妘姓所封。此云帝顓頊之後。互文錯見也。今山東兖州府鄒縣縣東南二十六里有古邾城。○趙氏岐曰。鄒本春秋邾子之國。至孟子時改曰鄒。此未"},{"e":"从邑。芻聲。","n":"側鳩切。三部。"}]},"恩":{"expl":"惠也。从心因聲。","rad":"心","fanqie":"烏痕切","vol":"10","duan":[{"e":"惠也。从心因。因亦聲。","n":"依韵會訂。烏㾗切。十三部。"}]},"令":{"expl":"發號也。从亼、卪。","rad":"卩","fanqie":"力正切","vol":"09","duan":[{"e":"發號也。","n":"号部曰。號者、嘑也。口部曰。嘑者、號也。發號者、發其號嘑以使人也。是曰令。人部曰。使者。令也。義相轉注。引伸爲律令、爲時令。詩箋曰。令、善也。按詩多言令。毛無傳。古文尚書言靈。見般庚、多士、多方。般庚正義引釋詁。靈、善也。葢今本爾雅作令、非古也。凡令訓善者、靈之假借字也。"},{"e":"从亼卪。","n":"號嘑者招集之卪也。故从亼卪會意。力正切。古音在十二部。"}]},"远":{"expl":"遼也。从辵袁聲。","rad":"辵","fanqie":"雲阮切","vol":"02","duan":[{"e":"遼也。从辵。袁聲。","n":"雲阮切。十四部。"}]},"宰":{"expl":"辠人在屋下執事者。从宀从辛。辛，辠也。","rad":"宀","fanqie":"作亥切","vol":"07","duan":[{"e":"辠人在屋下執事者。","n":"此宰之本義也。引伸爲宰制。"},{"e":"从宀。从辛。辛、辠也。","n":"辛卽辠之省。作亥切。一部。"}]},"何":{"expl":"儋也。从人可聲。","rad":"人","fanqie":"胡歌切","vol":"08","duan":[{"e":"儋也。","n":"何俗作荷。猶佗之俗作駝。儋之俗作擔也。商頌。百祿是何。何天之休。何天之龍。傳曰。何、任也。箋云。謂擔負。周易。何天之衢。虞翻曰。何、當也。何校滅耳。王肅云。何、荷擔也。又詩。何戈與祋。何蓑何笠。傳皆云。揭也。揭者、舉也。戈祋手舉之。蓑笠身舉之。皆擔義之引伸也。凡經曲作荷者皆後人所竄改。"},{"e":"一曰誰也。","n":"誰何孰三字皆問䛐。"}]},"西":{"expl":"鳥在巢上。象形。日在西方而鳥棲，故因以爲東西之西。凡西之屬皆从西。","rad":"西","fanqie":"先稽切","vol":"12","duan":[{"e":"鳥在巢上也。象形。","n":"下象巢。上象鳥。會意。上下皆非字也。故不曰會意而曰象形。鳥在巢上者、此篆之本義。今音先稽切。古音讀如詵、讀如𠎣。如西施亦作先施。漢書曰。西、遷也。古音在十二十三部。"},{"e":"日在㢴方而鳥㢴。","n":"上西、卽下文東西之西也。下西、西之本義也。"}]},"陈":{"expl":"宛丘，舜後嬀滿之所封。从𨸏从木，申聲。","rad":"𨸏","fanqie":"直珍切","vol":"14","duan":[{"e":"宛丘也。","n":"韵會有也。"},{"e":"舜後嬀滿之所封。","n":"毛傳諩曰。陳者、大皞虙戲氏之墟。帝舜之冑。有虞閼父者、爲周武王陶正。武王賴其利器用。與其神明之後。封其子嬀滿於陳。都於宛丘之側。是曰陳胡公。按今河南陳州府治是其地。許必言宛丘者、爲其字从𨸏也。毛傳曰。四方高中央下曰宛丘。卽釋丘之宛中曰宛丘也。陳本大皞之虛正字。俗叚爲敶列之敶。陳行而敶廢矣。"}]},"清":{"expl":"朖也。澂水之皃。从水青聲。","rad":"水","fanqie":"七情切","vol":"11","duan":[{"e":"朖也。澂水之皃。","n":"朖者、明也。澂而後明。故云澂水之皃。引伸之、凡潔曰淸。凡人潔之亦曰淸。同瀞。"},{"e":"从水。靑聲。","n":"七情切。十一部。"}]},"若":{"expl":"擇菜也。从艸、右。右，手也。一曰杜若，香艸。","rad":"艸","fanqie":"而灼切","vol":"01","duan":[{"e":"擇菜也。","n":"晉語。秦穆公曰。夫晉國之亂。吾誰使先若夫二公子而立之。以爲朝夕之急。此謂使誰先擇二公子而立之。若正訓擇。擇菜引伸之義也。"},{"e":"从艸右。右手也。","n":"此㑹意毛傳曰。若、順也。於雙聲叚借也。又假借爲如也、然也、乃也、汝也。又兼及之詞。五部。"}]},"诺":{"expl":"𧭭也。从言若聲。","rad":"言","fanqie":"奴各切","vol":"03","duan":[{"e":"𤻮也。","n":"𤻮者、應之俗字。說解中有此字。或偶爾从俗。或後人妄改。疑不能明也。大徐於此部增𤻮字。誤矣。口部曰。唯、諾也。唯諾有急緩之别。統言之則皆應也。"},{"e":"从言。若聲。","n":"奴各切。五部。"}]},"严":{"expl":"教命急也。从吅𠪚聲。","rad":"吅","fanqie":"語杴切","vol":"02","duan":[{"e":"敎命急也。","n":"嚴急㬪韵。趙注孟子曰。事嚴、喪事急。"},{"e":"从吅。","n":"敦促之意。"}]},"静":{"expl":"審也。从青爭聲。","rad":"青","fanqie":"疾郢切","vol":"05","duan":[{"e":"宷也。","n":"上林賦靚糚。張揖注曰。謂粉白黛黑也。按靚者、靜字之假借。采色詳宷得其宐謂之靜。考工記言畫繢之事是也。分佈五色。疏密有章。則雖絢爛之極。而無淟涊不鮮。是曰靜。人心宷度得宐。一言一事必求理義之必然。則雖緐勞之極而無紛亂。亦曰靜。引伸假借之義也。安靜本字當从立部之竫。"},{"e":"从靑。爭聲。","n":"疾郢切。十一部。"}]},"嘉":{"expl":"美也。从壴加聲。","rad":"壴","fanqie":"古牙切","vol":"05","duan":[{"e":"美也。","n":"見釋詁。又曰。嘉、善也。周禮。以嘉禮親萬民。鄭曰。嘉、善也。所以因人心所善者而爲之制。按誩部曰。譱、吉也。羊部曰。美與善同意。經有借假爲嘉者。如大雅、周頌毛傳皆曰假、嘉也是也。有借賀爲嘉者。覲禮古文余一人嘉之、今文嘉作賀是也。"},{"e":"从壴。","n":"壴者、陳樂也。故嘉从壴。"}]},"白":{"expl":"西方色也。陰用事，物色白。从入合二。二，陰數。凡白之屬皆从白。","rad":"白","fanqie":"㫄陌切","vol":"07","duan":[{"e":"西方色也。侌用事。物色白。从入合二。","n":"出者陽也。入者陰也。故从入。"},{"e":"二、侌數。","n":"說从二之恉。旁陌切。古音在五部。"}]},"允":{"expl":"信也。从儿㠯聲。","rad":"儿","fanqie":"樂準切","vol":"08","duan":[{"e":"信也。","n":"釋詁、毛傳皆曰。允、信也。詩仲允、漢表作中術。"},{"e":"从㠯儿。","n":"大徐作从儿㠯聲。㠯非聲也。今依韵會所據小徐本。㠯、用也。任賢勿貳是曰允。此會意字。余準切。十三部。"}]},"轩":{"expl":"曲輈藩車。从車干聲。","rad":"車","fanqie":"虚言切","vol":"14","duan":[{"e":"曲輈藩車也。","n":"謂曲輈而有藩蔽之車也。曲輈者、戴先生曰。小車謂之輈。大車謂之轅。人所乗欲其安。故小車暢轂梁輈。大車任載而已。故短轂直轅。艸部曰。藩者、屛也。服䖍注左傳、薛綜解東京賦、劉昭注輿服志皆云車有藩曰軒。皆同許說。許於藩車上必云曲輈者、以輈穹曲而上。而後得言軒。凡軒舉之義引申於此。曲輈、所謂軒轅也。杜注左傳於軒皆曰大夫車。定九年曰。犀軒、卿車。"},{"e":"从車。干聲。","n":"虚言切。十四部。藩俗作轓。"}]},"润":{"expl":"水曰潤下。从水閏聲。","rad":"水","fanqie":"如順切","vol":"11","duan":[{"e":"水曰潤下。","n":"語見洪範。"},{"e":"从水。閏聲。","n":"如順切。十三部。"}]},"信":{"expl":"誠也。从人从言。會意。","rad":"言","fanqie":"息晉切","vol":"03","duan":[{"e":"誠也。","n":"釋詁。誠、信也。"},{"e":"从人言。","n":"序說會意曰信武是也。人言則無不信者。故从人言。息晉切。十二部。古多以爲屈伸之伸。"}]},"磊":{"expl":"眾石也。从三石。","rad":"石","fanqie":"落猥切","vol":"09","duan":[{"e":"眾石皃。","n":"皃各本作也。今依廣韵訂。石三爲磊。猶人三爲衆。磊之言參也。古音在十六部。楚辭。石磊磊兮葛蔓蔓。"},{"e":"从三石。","n":"落猥切。古音在紙韵。是以亦作磥。"}]},"榆":{"expl":"榆，白枌。从木俞聲。","rad":"木","fanqie":"羊朱切","vol":"06","duan":[{"e":"榆白枌。","n":"見釋木。陳風東門之枌傳云。枌、白榆也。然則釋木榆白爲逗、枌爲句、顯然。許意亦如此讀。別榆一穜以起下也。榆莢可食。亦可爲𤖕。酉部所謂𨡭䤅也。"},{"e":"從木。俞聲。","n":"羊朱切。古音在四部。"}]},"纯":{"expl":"絲也。从糸屯聲。《論語》曰：“今也純，儉。”","rad":"糸","fanqie":"常倫切","vol":"13","duan":[{"e":"絲也。","n":"論語。麻冕、禮也。今也純。孔安國曰。純、絲也。此純之本義也。故其字从糸。按純與？音同。醇者、不澆酒也。叚純爲醇字。故班固曰。不變曰醇。不襍曰粹。崔覲說易曰。不襍曰純。不變曰粹。其意一也。美絲美酒、其不襍同也。不襍則壹、壹則大。故釋詁、毛傳、鄭箋皆曰。純、大也。文王純亦不巳。卽周易之純粹也。詩之純束讀如屯。國語之稛、左傳之？皆其字也。禮之純釋爲緣。實卽緣之音近叚借也。"},{"e":"从糸。屯聲。","n":"常倫切。十三部"}]},"廖":{"expl":"人姓。从广，未詳。當是省廫字尔。","rad":"广","fanqie":"力救切","vol":"09","duan":[]},"文":{"expl":"錯畫也。象交文。凡文之屬皆从文。","rad":"文","fanqie":"無分切","vol":"09","duan":[{"e":"錯畫也。","n":"錯當作逪、逪畫者䢒逪之畫也𦒱工記曰。靑與赤謂之文。逪畫之一耑也逪畫者、文之本義。彣彰者、彣之本義。義不同也。黃帝之史倉頡見鳥獸蹏迒之迹。知分理之可相別異也。初造書契。依類象形、故謂之文。"},{"e":"象交文。","n":"像兩紋交互也。紋者、文之俗字。無分切。十三部。"}]},"旭":{"expl":"日旦出皃。从日九聲。若勖。一曰明也。","rad":"日","fanqie":"許玉切","vol":"07","duan":[{"e":"日旦出皃。","n":"邶風。旭日始旦。傳曰。旭者、日始出。謂大昕之時。旭與曉雙聲。釋訓曰。旭旭、蹻蹻、憍也。郭云。皆小人得志憍蹇之皃。此其引伸叚借之義也。今詩旭旭作好好。同音叚借字也。"},{"e":"从日。九聲。讀若好。","n":"好各本作勗。誤。今依詩音義訂。按音義云許玉反。徐又許九反。是徐讀如朽。朽卽好之古音。朽之入聲爲許玉反。三讀皆於九聲得之。不知何時許九誤爲許元。集韵、類篇皆云許元切。徐邈讀今之音義又改元爲袁。使學者求其說而𣃔不能得矣。大徐許玉切。三部。"}]},"荣":{"expl":"桐木也。从木，熒省聲。一曰屋梠之兩頭起者爲榮。","rad":"木","fanqie":"永兵切","vol":"06","duan":[{"e":"桐木也。","n":"見釋木。按梧下云。梧桐木。榮下曰。桐木。此卽賈思勰靑桐、白桐之別也。白桐華而不實。材中樂器。靑桐則不中用。毛詩。椅桐梓漆。爰伐琴瑟。其白桐與。又云。其桐其椅。其實離離。則靑桐亦𧦝桐。渾言之也。郭注爾雅。於榮桐木曰。卽梧桐。於櫬梧曰。今梧桐皮靑者。本不誤。今本𠜂節。乃不可通。"},{"e":"從木。熒省聲。","n":"永兵切。十一部。"}]},"泽":{"expl":"光潤也。从水睪聲。","rad":"水","fanqie":"丈伯切","vol":"11","duan":[{"e":"光潤也。","n":"又水艸交厝曰澤。又借爲釋字。"},{"e":"从水。𥇡聲。","n":"丈伯切。古音𡉈五部。"}]},"岚":{"expl":"山名。从山，葻省聲。","rad":"山","fanqie":"盧含切","vol":"09","duan":[]},"温":{"expl":"水。出犍爲涪，南入黔水。从水𥁕聲。","rad":"水","fanqie":"烏魂切","vol":"11","duan":[{"e":"溫水。出楗爲符。","n":"句。"},{"e":"南入黔水。","n":"楗依王氏宋本從木。𥻳釋曰。漢𥓓犍爲皆作楗爲。是也。符各本作涪。誤。今正。地理志犍爲郡符下云。溫水、南至鄨。入黚水。黚水亦南至鄨。入江。按黚黔音同。黔水卽黚水。水經於江水曰。又東過枳縣西。延江水從牂柯郡北流西屈注之。枳縣今重慶府涪州治也。枳與涪陵縣壤接。今涪州城東北有黔江。南自貴州合諸水入焉。亦曰烏江。亦曰涪江。亦曰涪陵江。此水自西而東而北。源流二千三百里。詳見水道提綱。會貴州大定、貴陽、遵義、平越、石阡、思南六府及湖廣施南半府、四川酉陽、黔江、彭水、南川、涪州諸水。實巨川也。水經注延江篇曰。溫水、一曰煗水。出犍爲符縣而南入黚水。黚水亦出符縣南、與溫水會。俱南入鄨水。江水篇曰。華陽記曰。枳縣𡉈江州巴郡東四百里。治涪陵水會。皆烏江之源委也。漢志今本疑有奪字。以水經注正之。疑當云溫水至鄨入黚水。黚水亦出符至鄨。北入江。鄨非入江之地。今云至鄨入江。非例也。水經之延江水、於江水條曰枳縣西注江。於延江"}]},"郝":{"expl":"右扶風鄠、盩厔鄉。从邑赤聲。","rad":"邑","fanqie":"呼各切","vol":"06","duan":[{"e":"右扶風鄠盩庢鄉。","n":"鉉本如此。謂右扶風之鄠縣、盩庢縣皆有郝鄉也。玉篇作右扶風盩庢鄉。無鄠字。而鍇本作右扶風鄠鄉盩庢縣。脫落不完。汲古毛扆乃取以改舊本。可𥬇也。前志曰。右扶風盩庢。按在今陜西西安府盩庢縣。"},{"e":"从邑。赤聲。","n":"呼各切。五部。"}]},"姜":{"expl":"神農居姜水，以爲姓。从女羊聲。","rad":"女","fanqie":"居良切","vol":"12","duan":[{"e":"神農凥姜水。因㠯爲姓。","n":"晉語。司空季子曰。昔少典娶于有蟜氏。生黃帝、炎帝。黃帝以姬水成。炎帝以姜水成。成而異德。故黃帝爲姬。炎帝爲姜。韋注。成、謂所生長以成功也。渭水篇注曰。岐水又東逕姜氏城南爲姜水。引帝王世紀炎帝神農氏姜姓。母女登遊華陽。感神而生炎帝。長於姜水是其地。按姜姬字、葢後所製。"},{"e":"从女。羊聲。","n":"居良切。十部。"}]},"舒":{"expl":"伸也。从舍从予，予亦聲。一曰舒，緩也。","rad":"予","fanqie":"傷魚切","vol":"04","duan":[{"e":"伸也。","n":"經傳或假荼。或假豫。"},{"e":"从予。","n":"物予人得伸其意。"}]},"许":{"expl":"聽也。从言午聲。","rad":"言","fanqie":"虚呂切","vol":"03","duan":[{"e":"𦗟言也。","n":"𦗟從之言也。耳與聲相入曰𦗟。引伸之凡順從曰𦗟。許、或假爲所。或假爲御。下武傳。許、進也。卽御進也。東平王蒼正作昭茲來御。又爲鄦之叚借字。"},{"e":"从言。午聲。","n":"虚呂切。五部。"}]},"欧":{"expl":"吐也。从欠區聲。","rad":"欠","fanqie":"烏后切","vol":"08","duan":[{"e":"吐也。","n":"海外經。歐絲之野。一女子跪據樹歐絲。"},{"e":"从欠。區聲。","n":"烏后切。四部。"}]},"常":{"expl":"下帬也。从巾尚聲。","rad":"巾","fanqie":"市羊切","vol":"07","duan":[{"e":"下帬也。","n":"釋名曰。上曰衣。下曰裳。裳、障也。以自障蔽也。士冠禮。爵弁。服纁裳。皮弁。服素積。玄端。玄裳、黃裳、襍裳可也。禮記深衣。續衽鉤邊。要縫半下。今字裳行而常廢矣。"},{"e":"从巾。尙聲。","n":"从巾者、取其方幅也。引伸爲經常字。市羊切。十部。"}]},"周":{"expl":"密也。从用、口。","rad":"口","fanqie":"職畱切","vol":"02","duan":[{"e":"密也。","n":"密、山部曰山如堂者。引伸訓爲周緻也。左傳。晏子曰。淸濁小大。短長疾徐。哀樂剛柔。遟速高下。出入周疏。以相濟也。以周與疏反對。又襄二十七年。春。胥梁帶使諸喪邑者。具車徒以受地。必周。杜皆云。周、密也。按忠信爲周。謂忠信之人無不周密者。"},{"e":"从用口。","n":"善用其口則密。不密者皆由於口。職畱切。三部。"}]},"郑":{"expl":"京兆縣。周厲王子友所封。从邑奠聲。宗周之滅，鄭徙潧洧之上，今新鄭是也。","rad":"邑","fanqie":"直正切","vol":"06","duan":[{"e":"京兆縣。","n":"二志同。今陜西同州府華州州城北有故鄭城。"},{"e":"周厲王子友所封。","n":"前志曰。周宣王弟鄭桓公邑。"}]},"东":{"expl":"動也。从木。官溥說：从日在木中。凡東之屬皆从東。","rad":"東","fanqie":"得紅切","vol":"06","duan":[{"e":"動也。","n":"見漢律曆志。"},{"e":"從木。官溥說。從日在木中。","n":"木、榑木也。日在木中曰東。在木上曰杲。在木下曰杳。得紅切。九部。"}]},"瑜":{"expl":"瑾瑜，美玉也。从玉俞聲。","rad":"玉","fanqie":"羊朱切","vol":"01","duan":[{"e":"瑾瑜也。","n":"凡合二字成文。如瑾瑜、玟瑰之類。其義旣舉於上字。則下字例不復舉。俗本多亂之。此也字之上有美玉二字是。"},{"e":"从王。兪聲。","n":"羊朱切。古音在四部。"}]},"肖":{"expl":"骨肉相似也。从肉小聲。不似其先，故曰“不肖”也。","rad":"肉","fanqie":"私妙切","vol":"04","duan":[{"e":"骨肉相佀也。","n":"骨肉相似者、謂此人骨肉與彼人骨肉狀皃略同也。故字從肉。漢㓝法志假宵。列子假俏。"},{"e":"从肉。小聲。","n":"私妙切。二部。"}]},"苏":{"expl":"桂荏也。从艸穌聲。","rad":"艸","fanqie":"素孤切","vol":"01","duan":[{"e":"桂荏也。","n":"桂上鍇本有蘇字。此複寫隷字𠜂之未盡者。蘇、桂荏。釋艸文。內則注曰。薌蘇、桂之屬也。方言曰。蘇亦荏也。關之東西或謂之蘇。或謂之荏。郭樸曰。蘇、荏類。是則析言之則蘇荏二物。統言則不別也。桂荏今之紫蘇。蘇之叚借爲樵蘇。"},{"e":"从艸。穌聲。","n":"素孤切。五部。"}]},"攸":{"expl":"行水也。从攴从人，水省。","rad":"攴","fanqie":"以周切","vol":"03","duan":[{"e":"行水也。","n":"戴侗曰。唐本作水行攸攸也。其中從巛按當作行水攸攸也。行水順其性則安流攸攸而入於海。衞風傳浟浟、流皃是也。作浟者、俗變也。左傳說火曰。鬱攸從之。蒙葺公屋。火之行如水之行。故曰鬱攸。大雅曰。爲韓姞相攸。釋言。攸、所也。水之安行爲攸。故凡可安爲攸。又借爲？字。？、气行皃。水行之攸、气行之？皆主和緩。故或用攸。或用？。"},{"e":"从攴。从人。","n":"攴取引導之意人謂引導者。"}]},"丹":{"expl":"巴越之赤石也。象采丹井，一象丹形。凡丹之屬皆从丹。","rad":"丹","fanqie":"都寒切","vol":"05","duan":[{"e":"巴越之赤石也。","n":"巴郡、南越皆出丹沙。蜀都賦。丹沙赩熾出其坂。謂巴也。吳都賦。赬丹明璣。謂越也。丹者、石之精。故凡藥物之精者曰丹。"},{"e":"象采丹井。","n":"謂<>也。采丹之井、史記所謂丹穴也。蜀、吳二都賦注皆云。出山中、有穴。"}]},"柯":{"expl":"斧柄也。从木可聲。","rad":"木","fanqie":"古俄切","vol":"06","duan":[{"e":"斧柄也。","n":"見豳風毛傳。考工記曰。一欘有半謂之柯。注云。伐木之柯。柄長三尺。又廬人注曰。齊人謂柯斧柄爲椑。按柯斧者、大斧也。柯之假借爲枝柯。"},{"e":"從木。可聲。","n":"古俄切。十七部。"}]},"程":{"expl":"品也。十髮爲程，十程爲分，十分爲寸。从禾呈聲。","rad":"禾","fanqie":"直貞切","vol":"07","duan":[{"e":"程品也。","n":"大徐無程字。按此三字爲句。與䆃米也一例。淺人槩謂複字而刪之。品者、衆庶也。因衆庶而立之法則。斯謂之程品。上文言諸程品可證矣。荀卿曰。程者、物之準也。月令。陳祭器。按度程。注。程謂器所容也。漢書。張蒼定章程。如淳云。章、曆數之章術也。程者、權衡丈尺斗斛之平法也。"},{"e":"十髮爲程。一程爲分。","n":"一俗本作十。誤。大小徐舊本、漢制攷、小學紺珠皆不誤。百髮爲分。𣃔無是理。"}]},"拓":{"expl":"拾也。陳、宋語。从手石聲。","rad":"手","fanqie":"之石切","vol":"12","duan":[{"e":"拾也。","n":"有司徹篇。乃摭于魚腊俎。俎釋三个。其餘皆取之。摘下云。拓果樹實也。儀禮摭古文作摕。此實非一字。因雙聲而異。"},{"e":"陳宋語。","n":"方言。摭、取也。陳宋之閒曰摭。"}]},"韦":{"expl":"相背也。从舛囗聲。獸皮之韋，可以束枉戾相韋背，故借以爲皮韋。凡韋之屬皆从韋。","rad":"韋","fanqie":"宇非切","vol":"05","duan":[{"e":"相背也。","n":"故从舛。今字違行而韋之本義廢矣。酒誥。薄韋辳父。馬云。韋、違行也。據羣經音辨、則古文尙書當如是。"},{"e":"从舛。囗聲。","n":"宇非切。十五部。"}]},"孙":{"expl":"子之子曰孫。从子从系。系，續也。","rad":"系","fanqie":"思魂切","vol":"12","duan":[{"e":"子之子曰孫。","n":"爾雅釋親文也。子卑於父。孫更卑焉。故引申之義爲孫順、爲孫遁。字本皆作孫。經傳中作遜者皆非古也。至部？下解曰。从至。至而復孫。孫、遁也。字作孫不作遜。此許書無遜之證。春秋經。夫人孫于齊。公孫于齊。公羊傳曰。孫猶孫也。內諱奔謂之孫。穀梁傳曰。孫之爲言猶孫也。諱奔也。云猶孫者、謂如孫之退然自處於眇小。詩公孫碩膚箋云。孫讀當如公孫于齊之孫。孫之言孫遁也。周公孫遁。辟此成功之大美。書序。帝堯將孫于位。亦謂遜遁。此等字今皆俗改爲遜。絕非古字古義。惟孫順字唐書作愻。見心部。而俗亦以遜爲之。"},{"e":"从系子。","n":"系於子也。會意。思䰟切。十三部。"}]},"郭":{"expl":"齊之郭氏虚。善善不能進，惡惡不能退，是以亡國也。从邑𩫏聲。","rad":"邑","fanqie":"古博切","vol":"06","duan":[{"e":"齊之郭氏虛。","n":"謂此篆乃齊郭氏虚之字也。郭本國名。虚墟古今字。郭國旣亡謂之郭氏虛。如左傳言少昊之虛、昆吾之虚、大曍之虚、祝融之虚也。郭氏虛在齊境內。"},{"e":"善善不能進。惡惡不能退。是㠯亡國也。","n":"郭何以爲虚。職是故也。事見韓詩外傳。新序、風俗通皆同。亦有取此說春秋者。按莊二十四年經云。赤歸于曹。郭公。公羊傳曰。赤者何。曹無赤者。葢郭公也。郭公者何。失地之君也。榖梁傳曰。赤葢郭公也。何爲名也。禮、諸矦無外歸之義。外歸、非正也。左無傳。郭今以爲城？字。又以爲恢郭字。又左傳虢國字、公羊作郭。"}]},"李":{"expl":"果也。从木子聲。","rad":"木","fanqie":"良止切","vol":"06","duan":[{"e":"李果也。从木。子聲。","n":"良止切。一部。古李理同音通用。故行李與行理竝見。大李與大理不分。"},{"e":"古文。","n":"尙書音義曰。梓材音子。本亦作梓。馬云。古作梓字。治木器曰梓。正義曰。此古杍字。今文作梓。按正義本經作杍。音義本經作梓。據二家說、葢壁中古文作杍。而馬季長易爲梓匠之梓也。如馬說、是壁中文假借杍爲梓匠字也。"}]},"武":{"expl":"楚莊王曰：“夫武，定功戢兵。故止戈爲武。”","rad":"戈","fanqie":"文甫切","vol":"12","duan":[{"e":"楚莊王曰。","n":"莊、上諱也。不當用。古莊壯通用。謚法固取壯非取艸。周書。兵甲亟作、莊。睿圉克服、莊。勝敵志強、莊。武而不遂、莊。皆壯字也。後人以莊代之耳。此莊王必本作壯。若諱莊之字曰嚴、乃漢法。許則從左氏古文。典下云。莊都說。亦當作壯。晉語有壯馳茲。葢古姓本作壯。後乃盡改爲莊。"},{"e":"夫武定功戢兵。故止戈爲武。","n":"宣十二年左傳文。此檃桰楚莊王語以解武義。莊王曰。於文止戈爲武。是倉頡所造古文也。衹取定功戢兵者、以合於止戈之義也。文之會意已明。故不言从止戈。文甫切。五部。大雅履帝武敏傳曰。武、迹也。此武之別一義也。"}]},"孟":{"expl":"長也。从子皿聲。","rad":"子","fanqie":"莫更切","vol":"14","duan":[{"e":"長也。从子。皿聲。","n":"莫更切。古音在十部。讀如芒。爾雅。孟、勉也。此借孟爲猛。"}]},"嗑":{"expl":"多言也。从口盍聲。讀若甲。","rad":"口","fanqie":"候榼切","vol":"02","duan":[{"e":"多言也。从口。盍聲。讀若甲。","n":"𠊱榼切。八部。"}]},"羊":{"expl":"祥也。从𦫳，象頭角足尾之形。孔子曰：“牛羊之字以形舉也。”凡羊之屬皆从羊。","rad":"羊","fanqie":"與章切","vol":"04","duan":[{"e":"祥也。","n":"㬪韵。考工記注曰。羊、善也。按？義羑美字皆从羊。"},{"e":"从𦫳。象四足尾之形。","n":"謂干也。與章切。十部。"}]},"田":{"expl":"陳也。樹穀曰田。象四囗。十，阡陌之制也。凡田之屬皆从田。","rad":"田","fanqie":"待秊切","vol":"13","duan":[{"e":"敶也。","n":"各本作陳。今正。敶者、列也。田與敶古皆音陳。故以㬪韵爲訓。取其敶列之整齊謂之田。凡言田田者、卽陳陳相因也。陳陳當作敶敶。陳敬仲之後爲田氏。田卽陳字。叚田爲陳也。"},{"e":"樹榖曰田。","n":"穜菜曰圃。樹果曰園。見囗部。"}]},"赵":{"expl":"趨趙也。从走肖聲。","rad":"走","fanqie":"治小切","vol":"02","duan":[{"e":"趍趙也。从走。肖聲。","n":"治小切。"}]},"葛":{"expl":"絺綌艸也。从艸曷聲。","rad":"艸","fanqie":"古達切","vol":"01","duan":[{"e":"絺綌艸也。","n":"周南。葛之覃兮。爲絺爲綌。"},{"e":"从艸。曷聲。","n":"古達切。十五部。"}]},"昭":{"expl":"日明也。从日召聲。","rad":"日","fanqie":"止遙切","vol":"07","duan":[{"e":"日朙也。","n":"引伸爲凡明之偁。廟有昭穆。昭取陽明。穆取陰幽。皆本無正字。叚此二字爲之。自晉避司馬昭諱。不敢正讀。一切讀上饒反。而陸氏乃以入經典釋文。陋矣。又別製佋字。注云。廟昭穆。父爲佋南面。子爲穆北面。从人召聲。此冣爲不通。昭穆乃鬼神之偁。其字當从示。而从人何也。無識者又取以竄入說文人部中。其亂名改作有如此者。今人部𠜂佋。"},{"e":"从日。召聲。","n":"止遙切。二部。"}]},"龚":{"expl":"給也。从共龍聲。","rad":"共","fanqie":"俱容切","vol":"03","duan":[{"e":"給也。","n":"糸部曰。給、相足也。此與人部供音義同。今供行而龔廢矣。尚書甘誓、牧誓龔行天之罰。謂奉行也。漢魏晉唐引此無不作龔。與供給義相近。衞包作恭。非也。秦和鐘銘。龔夤天命。言奉敬天命也。"},{"e":"从共。龍聲。","n":"俱容切。九部。按俱容於共得聲。未詳。"}]},"迟":{"expl":"徐行也。从辵犀聲。《詩》曰：“行道遲遲。”","rad":"辵","fanqie":"直尼切","vol":"02","duan":[{"e":"徐行也。","n":"今人謂稽延爲遲。平聲。謂待之爲遲。去聲。"},{"e":"从辵。犀聲。","n":"直尼切。十五部。"}]},"申":{"expl":"神也。七月，陰气成，體自申束。从臼，自持也。吏臣（段注“臣”作“以” ）餔時聽事，申旦政也。凡申之屬皆从申。","rad":"申","fanqie":"失人切","vol":"14","duan":[{"e":"神也。","n":"神不可通。當是本作？。如巳巳也之例。謂此申酉之篆卽今引申之義也。淺人不得其例。妄改爲神。攷諸古說無有合者。律書曰。申者、言陰用事。申則萬物。故曰申。律曆志曰。申堅於申。天文訓曰。申者、申之也。皆以申釋申。爲許所本。而今本淮南改申之作呻之。其可𣢑一而巳。或曰神當作身。下云陰氣成體。釋名、晉書樂志、玉篇、廣韵皆云。申、身也。許說身字从申省聲。皆其證。此說近是。然恐尙非許意。"},{"e":"七月侌气成體自申束。","n":"韵會無體字。陰气成謂三陰成爲否卦也。古屈伸字作詘申。亦叚信。其作伸者俗字。或以羼入許書人部耳。韓子外儲說曰。申之束之。今本申譌紳。申者、引長。束者、約結。廣韵曰。申、伸也。重也。"}]},"明":{"expl":"照也。从月从囧。凡朙之屬皆从朙。","rad":"朙","fanqie":"武兵切","vol":"07","duan":[{"e":"照也。","n":"火部曰。照明也。小徐作昭。日部曰。昭、明也。大雅。皇矣傳曰。照臨四方曰明。凡明之至則曰明明。明明猶昭昭也。大雅大明、常武傳皆云。明明、察也。詩言明明者五。堯典言朙朙者一。禮記大學篇曰。大學之道。在明明德。鄭云。明明德、謂顯明其至德也。有駜。在公明明。鄭箋云。在於公之所但明明德也。引禮記大學之道在明明德夫由微而著。由著而極。光被四表。是謂明明德於天下。自孔穎達不得其讀而經義隠矣。"},{"e":"从月囧。","n":"从月者、月以日之光爲光也。从囧、取窗牖麗樓闓。明之意也。囧亦聲。不言者。舉會意包形聲也。武兵切。古音在十部。"}]},"霖":{"expl":"雨三日已往。从雨林聲。","rad":"雨","fanqie":"力尋切","vol":"11","duan":[{"e":"凡雨三日已往爲霖。","n":"左傳隱九年。春王三月癸酉。大雨霖以震。書始也。庚辰。大雨雪。亦如之。書時失也。凡雨自三日以往爲霖。平地尺爲大雪。按許直用傳文爲說也。已當作以。自三日以往、謂雨三日又不止。不定其日數也。雨三日止、不得謂霖矣。韋注國語亦曰。雨三日以上爲霖。若宋人注尚書云三日雨爲霖。失古義矣。釋天。久雨謂之淫。淫謂之霖。"},{"e":"从雨。林聲。","n":"力尋切。七部。"}]},"毛":{"expl":"眉髮之屬及獸毛也。象形。凡毛之屬皆从毛。","rad":"毛","fanqie":"莫袍切","vol":"08","duan":[{"e":"睂髮之屬及獸毛也。","n":"眉者、目上毛也。髮者、首上毛也。而者、須也。須者、而也。𦣞下之毛也。𩓾者、頰須也。頾、口上須也。及獸毛者、貴人賤畜也。"},{"e":"象形。","n":"莫袍切。古音二部。"}]},"潘":{"expl":"淅米汁也。一曰水名，在河南滎陽。从水番聲。","rad":"水","fanqie":"普官切","vol":"11","duan":[{"e":"淅米汁也。","n":"內則曰。其閒面垢。燂潘請靧。鄭云。潘、米瀾也。按瀾者、灡之省。力旦反。"},{"e":"从水。番聲。","n":"暜官切。十四部。經典釋文芳袁反。"}]},"钦":{"expl":"欠皃。从欠金聲。","rad":"欠","fanqie":"去音切","vol":"08","duan":[{"e":"欠皃。","n":"凡气不足而後欠。欽者、倦而張口之皃也。引伸之、乃欿然如不足謂之欽。詩晨風。憂心欽欽。傳曰。思望之心中欽欽然。小雅。𡔷鍾欽欽。傳曰。欽欽言使人樂。進也。皆言沖虛之意。尙書欽哉。皆令其惟恐失之也。釋詁曰。欽、敬也。攷虞夏商書言欽。周書則言敬。虞夏商書皆欽敬錯見。上曰欽若昊天、下曰敬授民時。又欽哉、不曰敬哉。葢欽與敬意略同而䛐有別也。周書言敬哉、不曰欽哉。惟多方曰。有夏之民。叨懫日欽。劓割夏邑。立政。帝欽罰之。欽字兩見。某氏傳皆訓爲敬。未知合書意否。"},{"e":"从欠。金聲。","n":"去音切。七部。欽欺欿歉皆雙聲㬪韵字。皆謂虛而能受也。"}]},"范":{"expl":"範軷也。从車，笵省聲。讀與犯同。","rad":"車","fanqie":"犯","vol":"14","duan":[{"e":"範軷也。","n":"三字句。其義已見上。故衹云範軷也。"},{"e":"从車。笵省聲。","n":"大徐音犯。廣韵防鋄切。七部。"}]},"夷":{"expl":"平也。从大从弓。東方之人也。","rad":"大","fanqie":"以脂切","vol":"10","duan":[{"e":"東方之人也。从大。从弓。","n":"各本作平也。从大从弓、東方之人也。淺人所改耳。今正。韵會正如是。羊部曰。南方蠻閩从虫。北方狄从犬。東方貉从豸。西方羌从羊。西南僰人、焦僥从人。葢在坤地頗有順理之性。惟東夷从大。大、人也。夷俗仁。仁者壽。有君子不死之國。按天大、地大、人亦大。大象人形。而夷篆从大。則與夏不殊。夏者、中國之人也。从弓者、肅愼氏貢楛矢石砮之類也。以脂切。十五部。出車、節南山、桑柔、召旻傳皆曰。夷、平也。此與君子如夷、有夷之行、降福孔夷傳夷易也同意。夷卽易之叚借也。易亦訓平。故叚夷爲易也。節南山一詩中平易分釋者、各依其義所近也。風雨傳曰夷悅也者、平之意也。皇矣傳曰夷常也者、謂夷卽彝之叚借也。凡注家云夷傷也者、謂夷卽痍之假借也。周禮注夷之言尸也者、謂夷卽尸之叚借也。尸、陳也。其他訓釋皆可以類求之。"}]},"蔡":{"expl":"艸也。从艸祭聲。","rad":"艸","fanqie":"蒼大切","vol":"01","duan":[{"e":"艸丯也。","n":"丯讀若介。丯字本無。今補。四篇曰。丯、艸蔡也。此曰。蔡、艸丯也。是爲轉注。艸生之散亂也。丯蔡曡韵。猶𦱊𦺝。此無丯字。則蔡當爲艸名。不廁此處矣。"},{"e":"从艸。祭聲。","n":"蒼大切。十五部。"}]},"晓":{"expl":"明也。从日堯聲。","rad":"日","fanqie":"呼鳥切","vol":"07","duan":[{"e":"朙也。","n":"此亦謂旦也。俗云天曉是也。引伸爲凡明之偁。方言。黨曉哲知也。楚謂之黨。或曰曉。齊宋之閒謂之哲。"},{"e":"从日。堯聲。","n":"呼鳥切。二部。曉昕二篆鉉本奪而綴於末。今依鍇本。"}]},"余":{"expl":"饒也。从食余聲。","rad":"食","fanqie":"以諸切","vol":"05","duan":[{"e":"饒也。从食。余聲。","n":"以諸切。五部。"}]},"宋":{"expl":"居也。从宀从木。讀若送。","rad":"宀","fanqie":"蘇統切","vol":"07","duan":[{"e":"凥也。","n":"此義未見經傳。名子者不以國。而魯定公名宋。則必取其本義也。"},{"e":"从宀木。讀若送。","n":"蘇綜切。九部。"}]},"坤":{"expl":"地也。《易》之卦也。从土从申。土位在申。","rad":"土","fanqie":"苦昆切","vol":"13","duan":[{"e":"地也。易之卦也。","n":"象傳曰。地勢坤。君子以厚德載物。說卦傳曰。坤、順也。按伏羲取天地之德爲卦。名曰乾坤。"},{"e":"从土申。","n":"會意。苦昆切。十三部。"}]},"敏":{"expl":"疾也。从攴每聲。","rad":"攴","fanqie":"眉殞切","vol":"03","duan":[{"e":"疾也。","n":"釋詁、毛傳同。"},{"e":"从攴。每聲。","n":"眉殞切。古音在一部。生民詩。履帝武敏。釋訓。每、拇也。謂敏爲拇之假借。拇、足大𢫾也。古作母。"}]},"上":{"expl":"高也。此古文上，指事也。凡丄之屬皆从丄。","rad":"丄","fanqie":"時掌切","vol":"01","duan":[{"e":"高也。此古文丄。","n":"古文上作𠄞。故帝下㫄下示下皆云从古文上。可以證古文本作𠄞。篆作丄。各本誤以丄爲古文。則不得不改篆文之上爲<>。而用上爲部首。使下文从𠄞之字皆無所統。示次於𠄞之恉亦晦矣。今正丄爲𠄞、[上竖为弓曲]爲丄。觀者勿疑怪可也。凡說文一書。以小篆爲質。必先舉小篆。後言古文作某。此獨先舉古文後言小篆作某。變例也。以其屬皆从古文上、不从小篆上。故出變例而別白言之。"},{"e":"𢫾（指）事也。","n":"凡𢫾事之文絕少。故顯白言之。不於一下言之者、一之爲𢫾事不待言也。象形者實有其物。日月是也。𢫾事者不泥其物而言其事。丄丅是也。天地爲形。天在上、地在下。地在上、天在下。則皆爲事。"}]},"韵":{"expl":"和也。从音員聲。裴光遠云：古與均同。未知其審。","rad":"音","fanqie":"王問切","vol":"03","duan":[]},"初":{"expl":"始也。从刀从衣。裁衣之始也。","rad":"刀","fanqie":"楚居切","vol":"04","duan":[{"e":"始也。","n":"見釋詁。"},{"e":"从刀衣。","n":"㑹意。楚居切。五部。"}]},"冬":{"expl":"四時盡也。从仌从夂。夂，古文終字。","rad":"仌","fanqie":"都宗切","vol":"11","duan":[{"e":"四時盡也。","n":"冬之爲言終也。考工記曰。水有時而凝。有時而釋。故冬从仌。"},{"e":"从仌。从𠔾。","n":"會意。𠔾亦聲。都宗切。九部。"}]},"慧":{"expl":"儇也。从心彗聲。","rad":"心","fanqie":"胡桂切","vol":"10","duan":[{"e":"儇也。","n":"人部曰。儇、慧也。二篆爲轉注。慧古多叚惠爲之。"},{"e":"从心。彗聲。","n":"胡桂切。十五部。"}]},"官":{"expl":"吏，事君也。从宀从𠂤。𠂤猶眾也。此與師同意。","rad":"𠂤","fanqie":"古丸切","vol":"14","duan":[{"e":"吏事君也。从宀𠂤。","n":"會意。古丸切。十四部。"},{"e":"𠂤猶眔也。","n":"𠂤不訓眔、而可聯之訓眔。以宀覆之、則治眔之意也。"}]},"王":{"expl":"天下所歸往也。董仲舒曰：“古之造文者，三畫而連其中謂之王。三者，天、地、人也，而參通之者王也。”孔子曰：“一貫三爲王。”凡王之屬皆从王。[李陽冰曰：“中畫近上。王者，則天之義。”]","rad":"王","fanqie":"雨方切","vol":"01","duan":[{"e":"天下所歸往也。","n":"見白虎通。王往曡韵。"},{"e":"董仲舒曰。古之造文者。三畫而連其中謂之王。三者、天地人也。而參通之者、王也。","n":"見春秋䋣露。引之說字形也。韋昭注國語曰。參、三也。"}]},"城":{"expl":"以盛民也。从土从成，成亦聲。","rad":"土","fanqie":"氏征切","vol":"13","duan":[{"e":"㠯盛民也。","n":"言盛者、如黍稷之在器中也。"},{"e":"从土成。","n":"左傳曰。聖王先成民而後致力於神。"}]},"景":{"expl":"光也。从日京聲。","rad":"日","fanqie":"居影切","vol":"07","duan":[{"e":"日灮也。","n":"日字各本無依文選張孟、陽七哀詩注訂。火部曰。光者、明也。左傳曰。光者遠而自他有燿者也。日月皆外光。而光所在處物皆有陰。光如鏡故謂之景。車牽箋云。景、明也。後人名陽日光。名光中之陰曰影。別製一字。異義異音。斯爲過矣。爾雅、毛詩皆曰。景、大也。其引伸之義也。"},{"e":"从日。京聲。","n":"居影切。古音在十部。讀如姜。"}]},"杜":{"expl":"甘棠也。从木土聲。","rad":"木","fanqie":"徒古切","vol":"06","duan":[{"e":"甘棠也。","n":"召南。蔽芾甘棠。毛曰。甘棠、杜也。釋木曰。杜甘棠。本無不合。棠不實。杜實而可食。則謂之甘棠。凡實者皆得謂之杜。則皆得謂之甘棠也。牡棠牝杜、析言之也。杜得偁甘棠、互言之也。釋木又曰。杜、赤棠。白者棠。魏風傳用之。此以其木色之異異其名。與杜甘棠說異。卽與分牡牝說異。爲許所不取。戴先生曰。爾雅謂杜甘曰棠。毛公失其句讀。葢依陸璣疏白棠卽甘棠、子美。赤棠卽杜、子澀。爲此說耳。非許意。亦非爾雅意也。先生又曰。棃山樆。謂棃山生曰樆。榆白枌。謂榆之白者曰枌。今按毛傳云。枌白榆也。誠當於白爲讀。漢書音義云。離山棃也。是爾雅當同意義乙其字矣。"},{"e":"从木。土聲。","n":"徒古切。五部。借以爲杜塞之杜。"}]},"成":{"expl":"就也。从戊丁聲。","rad":"戊","fanqie":"氏征切","vol":"14","duan":[{"e":"就也。从戊。丁聲。","n":"氏征切。十一部。"}]},"孔":{"expl":"通也。从𠃉从子。𠃉，請子之候鳥也。𠃉至而得子，嘉美之也。古人名嘉字子孔。","rad":"𠃉","fanqie":"康董切","vol":"12","duan":[{"e":"通也。","n":"通者達也。於易卦爲泰。孔訓通、故俗作空穴字多作孔。其實空者、竅也。作孔爲叚借。"},{"e":"嘉美之也。","n":"各本無此四字。由淺人謂與下複而刪之。今依韵會補。也當作䛐。䛐者、意內而外也。通爲吉。？爲凶。故凡言孔者、皆所以嘉美之。毛傳曰。孔、甚也。是其義。甚者、尤安樂也。或曰。詩言亦孔之醜。豈嘉美之乎。曰。此卽今甚字通於美惡之意也。"}]},"顾":{"expl":"還視也。从頁雇聲。","rad":"頁","fanqie":"古慕切","vol":"09","duan":[{"e":"還視也。","n":"還視者、返而視也。檜風箋云。迴首曰顧。析言之爲凡視之偁。鄉黨。賓不顧矣。謂還視也。車中內顧。苞氏謂前視不過衡軛。旁視不過輢較。則顧猶視也。又引伸爲臨終之命曰顧命。又引伸爲語將轉之詞。"},{"e":"从𩑋。雇聲。","n":"古慕切。五部。"}]},"吕":{"expl":"𦟝骨也。象形。昔太嶽爲禹心呂之臣，故封呂矦。凡呂之屬皆从呂。","rad":"呂","fanqie":"力舉切","vol":"07","duan":[{"e":"𦟝骨也。象形。","n":"吕象顆顆相承。中象其系聯也。沈氏彤釋骨曰。項大椎之下二十一椎通曰脊骨、曰脊椎、曰膂骨。或以上七節曰背骨。第八節以下乃曰膂骨。力舉切。五部。"},{"e":"昔大嶽爲禹心呂之臣。故封呂矦。","n":"周語。大子晉曰。伯禹念前之非度。釐改制量。象物天地。比類百則。儀之于民。而度之于羣生。共之從孫四嶽佐之。高高下下。疏川道滯。帥象禹之功。度之于軌儀。莫非嘉績。克厭帝心。皇天嘉之。胙以天下。賜姓曰姒。氏曰有夏。謂其能以嘉祉殷富生物也。胙四嶽國。命爲矦伯。賜姓曰姜。氏曰有吕。謂其能爲禹股肱心膂。以養物豐民人也。按曰共之從孫。賈逵、韋昭皆曰。共、共工也。外傳曰四嶽。內傳曰大嶽。一也。官名也。外傳以祉訓姒。以殷富訓夏。以膂訓呂。以養訓姜。韋解云。呂之爲言膂也。是呂膂各字。呂者、國名。以國爲氏。許云。大嶽爲禹心呂之臣。故封呂矦。膂爲小篆呂。是許所據國語股肱心膂作股肱心呂。本無二字。後之爲國語學者不得其解。乃以氏曰有呂作古文。股肱心膂作小篆。韋氏習而不察。乃云呂之爲言膂矣。以心呂之意名其地。而矦之。而氏之。潛夫論曰。宛西三十里有呂。酈道元、徐廣、司馬貞說皆同。宛城今南陽府治附郭南陽縣是也。許自序曰。大"}]},"宁":{"expl":"願詞也。从丂寍聲。","rad":"丂","fanqie":"奴丁切","vol":"05","duan":[{"e":"願䛐也。","n":"其意爲願則其言爲寧。是曰意內言外。寍部曰。寍、安也。今字多假寧爲寍。寧行而寍廢矣。古文尙書葢有寍字。陸氏於大禹謨曰。寍、安也。說文安寍字如此。寧、願詞也。此陸氏依許分別二字。今本經宋開寶閒改竄。不可讀。"},{"e":"从丂。寍聲。","n":"奴丁切。十一部。"}]},"宫":{"expl":"室也。从宀，躳省聲。凡宮之屬皆从宮。","rad":"宮","fanqie":"居戎切","vol":"07","duan":[{"e":"室也。","n":"釋宫曰。宫謂之室。室謂之宫。郭云。皆所以通古今之異語。明同實而兩名。按宫言其外之圍繞。室言其內。析言則殊。統言不別也。毛詩。作于楚宫。作于楚室。傳曰。室猶宫也。此統言也。宫自其圍繞言之。則居中謂之宫。五音宫商角徵羽。劉歆云。宫、中也。居中央。唱四方。唱始施生。爲四聲綱也。"},{"e":"从宀。躳省聲。","n":"按說宫謂从宀吕會意。亦無不合。宀繞其外。吕居其中也。吕者、？骨也。居人身之中者也。居戎切。九部。"}]},"世":{"expl":"三十年爲一丗。从卅而曳長之。亦取其聲也。","rad":"卅","fanqie":"舒制切","vol":"03","duan":[{"e":"三十年爲一世。","n":"論語。如有王者。必世而後仁。孔曰。三十年曰世。按父子相繼曰世。其引伸之義也。"},{"e":"从𠦃而曳長之。","n":"曳長之、謂末筆也。"}]},"俊":{"expl":"材千人也。从人夋聲。","rad":"人","fanqie":"子峻切","vol":"08","duan":[{"e":"材過千人也。","n":"大徐本無過字。尹文子曰。千人才曰俊。萬人曰傑。淮南泰俗訓曰。智過萬人者謂之英。千人者謂之俊。百人者謂之豪。十人者謂之傑。春秋繁露曰。萬人者曰英。千人者曰俊。百人者曰傑。十人者曰豪。皋陶謨鄭注。曰才德過千人爲俊。百人爲乂。呂氏春秋孟秋紀高注曰。才過萬人曰桀。千人曰俊。王逸注懷沙曰。千人才爲俊。一國高爲桀。諸家說俊皆同。惟月令正義引蔡氏辨名記云。十人曰𨕖。倍𨕖曰俊。萬人曰桀。其說不同。方言曰。𡤼、俊也。遵、俊也。○又按月令疏蔡氏下奪引字。辨名記卽白虎通之別名記。古文記二百十四篇之一也。禮運及左傳宣十五年疏皆引辨名記云。倍人曰茂。十人曰𨕖。倍𨕖曰俊。千人曰英。倍英曰賢。萬人曰桀。倍桀曰聖。語較完。而白虎通引別名記。五人曰茂。十人曰𨕖。百人曰俊。千人曰英。倍英曰賢。萬人曰傑。萬傑曰聖。又不同。乖異。"},{"e":"从人。夋聲。","n":"子峻切。十三部。按尙書以畮爲俊。山海經以俊爲舜。"}]},"宸":{"expl":"屋宇也。从宀辰聲。","rad":"宀","fanqie":"植鄰切","vol":"07","duan":[{"e":"屋宇也。","n":"屋者、以宫室上覆言之。宸謂屋邊。故古書言柍桭者、卽楝宇也。甘泉賦。日月纔經於柍桭。伏虔曰。柍、中央也。桭、屋梠也。魏都賦。旅楹閑列。暉鑒柍桭。張載曰。柍、中央也。桭、宇檼也。是知柍桭卽上棟下宇之謂。柍卽央字。桭卽宸字。西京賦。消氛埃於中宸。集重陽之精微。中宸卽柍桭。韋昭注國語云。宸、屋𩅸也。宇、邊也。若玉篇引賈逵云宸屋之奧者、當亦是國語注。而其說異矣。"},{"e":"从宀。辰聲。","n":"植鄰切。十三部。"}]},"桐":{"expl":"榮也。从木同聲。","rad":"木","fanqie":"徒紅切","vol":"06","duan":[{"e":"榮也。從木。同聲。","n":"徒紅切。九部。"}]},"汤":{"expl":"熱水也。从水昜聲。","rad":"水","fanqie":"土郎切","vol":"11","duan":[{"e":"𤍽水也。从水。昜聲。","n":"土郎切。十部。又始陽切。湯湯水盛。"}]},"捷":{"expl":"獵也。軍獲得也。从手疌聲。《春秋傳》曰：“齊人來獻戎捷。”","rad":"手","fanqie":"疾葉切","vol":"12","duan":[{"e":"獵也。","n":"以㬪韵爲訓。謂如逐禽而得之也。"},{"e":"軍獲得也。","n":"小雅。一月三捷。傳曰。捷、勝也。箋云。往則庶乎一月之中三有勝功。春秋經。齊矦來獻戎捷。易。晝日三接。內則。接以大牢。鄭注皆讀爲捷、勝也。是古文叚借字也。又按大雅征夫捷捷、言樂事也。又有？傳曰。業、大板也。捷業如鋸齒。皆其引申之義。"}]},"罗":{"expl":"以絲罟鳥也。从网从維。古者芒氏初作羅。","rad":"网","fanqie":"魯何切","vol":"07","duan":[{"e":"㠯絲罟鳥也。","n":"釋器。鳥罟謂之羅。王風傳曰。鳥網爲羅。"},{"e":"从网。从維。","n":"會意。魯何切。十七部。或作罹。俗異用。"}]},"菁":{"expl":"韭華也。从艸青聲。","rad":"艸","fanqie":"子盈切","vol":"01","duan":[{"e":"韭華也。","n":"周禮。菁菹。先鄭曰。菁菹、韭華菹也。今各本脫華字。則何以別於上文之韭菹乎。廣雅曰。韭其華謂之菁。若南都賦曰秋韭冬菁、則是二物。史游所云老菁冬日藏也。"},{"e":"从艸。靑聲。","n":"子盈切。十一部。"}]},"彤":{"expl":"丹飾也。从丹从彡。彡，其畫也。","rad":"丹","fanqie":"徒冬切","vol":"05","duan":[{"e":"丹飾也。","n":"春秋經曰。丹桓宫楹。"},{"e":"从丹彡。","n":"以丹拂拭而涂之。故从丹彡。彡者、毛飾畫文也。飾拭古今字。"}]},"延":{"expl":"長行也。从㢟丿聲。","rad":"㢟","fanqie":"以然切","vol":"02","duan":[{"e":"長行也。","n":"本義訓長行。引伸則專訓長。方言曰。延長也。凡施於年者謂之延。又曰。延徧也。"},{"e":"从㢟。厂聲。","n":"厂部曰。象抴引之形。余制切。虒延？皆以爲聲。今篆體各異。非也。厂延虒？古音在十六部。故大雅施於條枚。呂氏春秋、韓詩外傳、新序皆作延于條枚。延音讀如移也。今音以然切。則十四部。"}]},"张":{"expl":"施弓弦也。从弓長聲。","rad":"弓","fanqie":"陟良切","vol":"12","duan":[{"e":"𢻱弓弦也。","n":"𢻱各本作施。今正。𢻱、敷也。張弛、本謂弓施弦解弦。引申爲凡作輟之稱。禮記曰。張而不弛。文武弗能也。弛而不張。文武弗爲也。一張一弛。文武之道也。"},{"e":"从弓。長聲。","n":"陟良切。十部。"}]},"芸":{"expl":"艸也。似目宿。从艸云聲。《淮南子》說：“芸艸可以死復生。”","rad":"艸","fanqie":"王分切","vol":"01","duan":[{"e":"艸也。佀目宿。","n":"夏小正。正月采芸。爲廟采也。二月榮芸。月令。仲冬芸始生。注。芸、香艸。高注淮南、呂覽皆曰。芸、芸蒿。菜名也。呂覽曰。菜之美者、陽華之芸。注。芸、芳菜也。賈思勰引倉頡解詁曰。芸蒿似斜蒿。可食。沈括曰。今謂之七里香者是也。葉類豌豆。其葉極芬香。古人用以藏書辟蠧。採置席下。能去蚤蝨。"},{"e":"从艸。云聲。","n":"王分切。十三部。"}]},"曹":{"expl":"獄之兩曹也。在廷東。从㯥，治事者；从曰。","rad":"曰","fanqie":"昨牢切","vol":"05","duan":[{"e":"獄㒳曹也。","n":"㒳曹、今俗所謂原吿被吿也。曹猶類也。史記曰。遣吏分曹逐捕。古文尙書。㒳造具備。史記㒳造一作㒳遭。㒳遭、㒳造卽㒳曹。古字多假借也。曹之引伸爲輩也。羣也。"},{"e":"从㯥。在廷東也。","n":"㒳曹在廷東。故从二東之㯥。其制未聞也。"}]},"瑞":{"expl":"以玉爲信也。从玉、耑。","rad":"玉","fanqie":"是僞切","vol":"01","duan":[{"e":"以玉爲信也。","n":"典瑞。掌玉瑞玉器之藏。注云。人執以見曰瑞。禮神曰器。又云。瑞、節信也。說文卪下云。瑞信也。是瑞卪二字爲轉注。禮神之器亦瑞也。瑞爲圭璧璋琮之總偁。自璧至瑁十五字皆瑞也。故總言之。引伸爲祥瑞者、亦謂感召若符節也。"},{"e":"从王。耑聲。","n":"耑聲在十四部。而瑞揣圌字音轉入十五部。唐韻是僞切。又入十六部。"}]},"德":{"expl":"升也。从彳㥁聲。","rad":"彳","fanqie":"多則切","vol":"02","duan":[{"e":"𦫵也。","n":"𦫵當作登。辵部曰。遷、登也。此當同之。德訓登者。公羊傳。公曷爲遠而觀魚。登來之也。何曰。登讀言得。得來之者、齊人語。齊人名求得爲得來。作登來者、其言大而急。由口授也。唐人詩。千水千山得得來。得卽德也。登德雙聲。一部與六部合韵又冣近。今俗謂用力徙前曰德。古語也。"},{"e":"从彳。𢛳聲。","n":"多則切。一部。"}]},"左":{"expl":"手相左助也。从𠂇、工。凡左之屬皆从左。","rad":"左","fanqie":"則箇切","vol":"05","duan":[{"e":"𠂇手相左也。","n":"各本俱誤。今正。左者、今之佐字。說文無佐也。𠂇者、今之左字。𠂇部曰。左手也。謂左助之手也。以手助手是曰左。以口助手是曰右。"},{"e":"从𠂇工。","n":"工者、左助之意。則箇切。十七部。"}]},"离":{"expl":"黃倉庚也。鳴則蠶生。从隹离聲。","rad":"隹","fanqie":"呂支切","vol":"04","duan":[{"e":"離黃、","n":"逗。各本無離。淺人誤刪。如巂周刪巂之比。依爾雅音義、廣韵補。"},{"e":"倉庚也。","n":"豳風毛傳曰。倉庚、離黃也。月令注云。倉庚、驪黃也。釋鳥曰。倉庚、？黃也。又曰。？黃、楚雀。又曰。倉庚、商庚。然則離黃一物四名。按說文離？不類廁。則不謂一物。又按毛傳黃鳥、搏黍也。不云卽倉庚。倉庚下亦不云卽黃鳥。然則黃鳥非倉庚。焦氏循云。鄭箋稱黃鳥宜食粟。又云緜蠻、小鳥皃。顯非倉庚。玉裁謂。葢今之黃雀也。方言云？黃或謂之黃鳥。此方俗語言之偶同耳。陸機乃誤以倉庚釋黃鳥。"}]},"之":{"expl":"出也。象艸過屮，枝莖益大，有所之。一者，地也。凡之之屬皆从之。","rad":"之","fanqie":"止而切","vol":"06","duan":[{"e":"出也。","n":"引伸之義爲往。釋詁曰之往是也。按之有訓爲此者。如之人也。之德也。之條條。之刀刀。左傳。鄭人醢之、三人也。召南毛傳曰。之事、祭事也。周南曰。之子、嫁子也。此等之字皆訓爲是。之有訓爲上出者。戴先生釋梓人曰。頰側上出者曰之。下垂者曰而。須鬣是也。"},{"e":"象艸過屮。","n":"過於屮也。"}]},"马":{"expl":"怒也。武也。象馬頭髦尾四足之形。凡馬之屬皆从馬。","rad":"馬","fanqie":"莫下切","vol":"10","duan":[{"e":"怒也。武也。","n":"以曡韵爲訓。亦門聞也、戸護也之例也。釋名曰。大司馬。馬、武也。大揔武事也。"},{"e":"象馬頭髦尾四足之形。","n":"古、籒文皆以彡象髦。右建奏事。事下。建讀之曰。誤書馬字。與尾當五。今乃四。不足一。上譴死矣。莫下切。古音在五部。"}]},"里":{"expl":"衣内也。从衣里聲。","rad":"衣","fanqie":"良止切","vol":"08","duan":[{"e":"衣內也。","n":"引伸爲凡在內之偁。"},{"e":"从衣。里聲。","n":"良止切。一部。"}]},"辕":{"expl":"輈也。从車袁聲。","rad":"車","fanqie":"雨元切","vol":"14","duan":[{"e":"輈也。","n":"攷工記。輈人爲輈。車人爲大車之轅。是輈與轅别也。許渾言之者、通偁則一也。轅之言如攀援而上也。"},{"e":"从車。袁聲。","n":"雨元切。十四部。"}]},"冶":{"expl":"銷也。从仌台聲。","rad":"仌","fanqie":"羊者切","vol":"11","duan":[{"e":"銷也。","n":"銷者、鑠金也。仌之融如鑠金然。故鑪鑄亦曰冶。易。野容誨淫。陸德明本作冶容。按野、冶皆蠱之叚借也。張衡賦言妖蠱。今言妖冶。"},{"e":"从仌。台聲。","n":"聲葢衍。台者、悅也。仌台悅而化。會意。冶今音羊者切。古音讀如與。在五部。或曰台雙聲也。故以爲聲。"}]},"小":{"expl":"物之微也。从八，丨見而分之。凡小之屬皆从小。","rad":"小","fanqie":"私兆切","vol":"02","duan":[{"e":"物之微也。从八丨見而八分之。","n":"八、別也。象分別之形。故解从八爲分之。丨才見而輒分之。會意也。凡㮯物分之則小。私兆切。二部。"}]},"崔":{"expl":"大高也。从山隹聲。","rad":"山","fanqie":"胙回切","vol":"09","duan":[{"e":"大高也。","n":"齊風。南山崔崔。傳曰。崔崔、高大也。此云大高。未知孰是。嵬下曰。山石崔嵬。高而不平也。亦卽毛傳之土山戴石曰崔嵬也。"},{"e":"从山。隹聲。","n":"聲字鉉無。今補。胙回切。十五部。按小徐無此篆。大徐此篆在部末。非其次。玉篇亦本無崔字。於部末補之。疑許葢本無此。莊子。山林之畏隹。隹卽今崔也。但人部有催、手部有摧、則山部當有崔矣。"}]},"漆":{"expl":"水。出右扶風杜陵岐山，東入渭。一曰入洛。从水桼聲。","rad":"水","fanqie":"親吉切","vol":"11","duan":[{"e":"漆水。出右扶風杜陵岐山。東入渭。","n":"二志皆杜陵屬京兆尹、杜陽屬右扶風。此杜陵當作杜陽。杜陽、今陝西鳳翔府麟遊縣是其地。周公劉居豳、今陝西邠州是其地。漢之漆。栒邑二縣也。太王遷𨙸、今鳳翔府岐山夫風二縣是其地。漢之杜陽南、美陽北也。大雅曰。民之初生。自土漆沮。傳曰。漆、漆水。沮、沮水也。又曰。周原、漆沮之閒也。周頌潛傳又曰。漆沮、岐州之二水也。據毛說則漆沮二水、實在岐周之地。小雅吉日傳但云漆沮之水。麀鹿所生。其解必同大雅、周頌。許云漆水出杜陽。正岐周地也。此漆沮在涇西。禹貢道渭又東過漆沮、則在涇東。與岐周無涉。玉裁謂水經曰。漆水出扶風杜陽縣俞山。東北入於渭。正與說文合。惟岐作俞耳。酈氏引開山圖曰。岐山在杜陽北、長安西。有渠謂之漆渠。酈又云。漆水出杜陽縣之漆溪。謂之漆渠。漆渠合岐水。與橫水合。東注雍水。又合杜水。南注於渭。郭樸山海經注云。今漆水出岐山。皆與水經合。而前志右扶風漆縣下云。漆水在縣西。以地望準之、葢此漆水出豳地。漢漆縣"},{"e":"从水。桼聲。","n":"四字依水經注所引在此。小徐本从某某聲、往往閒在兩義之中。不同大徐。皆小徐爲古本也。親吉切。十二部。"}]},"乐":{"expl":"五聲八音緫名。象鼓鞞。木，虡也。","rad":"木","fanqie":"玉角切","vol":"06","duan":[{"e":"五聲八音總名。","n":"樂記曰。感於物而動。故形於聲。聲相應。故生變。變成方。謂之音。比音而樂之。及干戚羽旄謂之樂。音下曰。宮商角徵羽、聲也。絲竹金石匏土革木、音也。樂之引伸爲哀樂之樂。"},{"e":"𧰼𡔷鞞。","n":"鞞當作？。俗人所改也。𧰼鼓鼙、謂？也。𡔷大？小。中𧰼𡔷。兩㫄𧰼？也。樂器多矣。獨像此者。𡔷者春分之音。易曰。雷出地奮豫。先王以作樂崇德。是其意也。"}]},"黎":{"expl":"履黏也。从黍，𥝢省聲。𥝢，古文利。作履黏以黍米。","rad":"黍","fanqie":"郎奚切","vol":"07","duan":[{"e":"履黏也。","n":"釋詁曰。黎、衆也。衆之義行而履黏之義廢矣。古亦以爲黧黑字。"},{"e":"从黍。𥝤省聲。","n":"𥝤省者、不欲重禾也。郞奚切。十五部。"}]},"甫":{"expl":"男子美稱也。从用、父，父亦聲。","rad":"用","fanqie":"方矩切","vol":"03","duan":[{"e":"男子之美偁也。","n":"春秋。公及邾儀父盟于蔑。穀梁傳曰。儀、字也。父猶傅也。男子之美稱也。士冠禮。字辭曰。伯某甫。仲叔季惟其所當。注。伯仲叔季、長幼之稱。甫是丈夫之美稱。按甫者、男子美偁。某甫者、若言尼甫、嘉甫、孔甫。謂之且字。且者、薦也。五十以伯仲乃謂之字。以下一字爲伯仲叔季之薦。故曰且字也。甫則非字。凡男子皆得偁之。以男子始冠之偁、引伸爲始也。又引伸爲大也。"},{"e":"从用父。","n":"可爲人父也。"}]},"锦":{"expl":"襄邑織文。从帛金聲。","rad":"帛","fanqie":"居飲切","vol":"07","duan":[{"e":"襄邑織文也。","n":"漢地理志、郡國志陳畱郡屬縣有襄邑。今河南歸德府睢州治卽故縣地。地理志云。縣有服官。李善引陳畱記云。襄邑渙水出其南。睢水經其北。傳云。睢渙之閒出文章。故其黼黻絺繡。日月華蟲。以奉宗廟御服焉。司馬彪輿服志云。襄邑歲獻織成虎文。按許以漢法釋古。謂若今之襄邑織文卽經典之錦文也。毛傳。貝、逗錦文也。禹貢。厥匪織貝。鄭注云。貝、錦名也。凡爲織者。先染其絲。乃織之。則成文矣。禮記云。士不衣織。"},{"e":"从帛。金聲。","n":"居飮切。七部。"}]},"湛":{"expl":"没也。从水甚聲。一曰湛水，豫章浸。","rad":"水","fanqie":"宅減切","vol":"11","duan":[{"e":"𣳚也。","n":"古書浮沈字多作湛。湛沈古今字。沉又沈之俗也。下文云。𣳚、湛也。二字轉注。"},{"e":"从水。甚聲。","n":"按直林切。七部。大徐宅減切。未知古義古音也。凡湛字引伸之義甚多。其音不一。要其古音則同直林切而已。"}]},"百":{"expl":"十十也。从一、𪞶。數，十百爲一貫。相章也。","rad":"𪞶","fanqie":"博陌切","vol":"04","duan":[{"e":"十十也。从一白。","n":"博陌切。五部。"},{"e":"數。","n":"句。"}]},"笙":{"expl":"十三簧。象鳳之身也。笙，正月之音。物生，故謂之笙。大者謂之巢，小者謂之和。从竹生聲。古者隨作笙。","rad":"竹","fanqie":"所庚切","vol":"05","duan":[{"e":"十三簧。","n":"蒙上管樂而言。故不云管樂也。大鄭周禮注曰。笙十三簧。按廣雅云笙十三管。亦每管有簧也。"},{"e":"象鳳之身也。笙、正月之音。物生。故謂之笙。","n":"白虎通曰。八音、匏曰笙。匏之爲言施也。在十二月萬物始施而牙。笙者、大蔟之氣。象萬物之生。故曰笙。釋名曰。笙、生也。象物貫地而生也。按禮經。東方鐘磬謂之笙鐘、笙磬。笙猶生也。東爲陽中。萬物以生。是以東方鐘磬謂之笙也。初生之物必細。故方言云。笙、細也。竽、大笙也。故竽可訓大。"}]},"煜":{"expl":"熠也。从火昱聲。","rad":"火","fanqie":"余六切","vol":"10","duan":[{"e":"燿也。","n":"此以雙聲爲訓。"},{"e":"从火。昱聲。","n":"余六切。古音在七部。昱从立聲。煜从昱聲。本音皆在七部。廣韵廿六緝。煜爲立切。古音也。"}]},"逸":{"expl":"失也。从辵、兔。兔謾訑善逃也。","rad":"兔","fanqie":"夷質切","vol":"10","duan":[{"e":"失也。","n":"此以曡韵爲訓。亡逸者、本義也。引伸之爲逸游、爲暇逸。"},{"e":"从辵兔。","n":"會意。夷質切。十二部。"}]},"培":{"expl":"培敦。土田山川也。从土咅聲。","rad":"土","fanqie":"薄回切","vol":"13","duan":[{"e":"培敦、","n":"逗。"},{"e":"土田山川也。","n":"左傳。祝鮀曰。分魯土田倍敦。釋文曰。倍本亦作陪。許所見作培爲是矣。杜云。倍、增也。敦厚也。左氏但言土田。而魯頌曰。錫之山川。土田附庸。大雅曰。告于文人。錫山土田。毛傳曰。諸侯有大功德。賜之名山土田附庸。魯頌箋云。策命伯禽。使爲君於東。加賜之以山川土田及附庸。令專統之。王制曰。名山大川不以封。諸侯附庸則不得專臣也。按封建所加厚曰培敦。許合詩以釋左也。引申爲凡裨補之偁。"}]},"竹":{"expl":"冬生艸也。象形。下垂者，箁箬也。凡竹之屬皆从竹。","rad":"竹","fanqie":"陟玉切","vol":"05","duan":[{"e":"冬生艸也。","n":"云冬生者、謂竹胎生於冬。且枝葉不凋也。云竹者、爾雅竹在澤艸。山海經有云其艸多竹。故謂之冬生艸。戴凱之云。植物之中有艸木竹、猶動品之中有魚鳥獸也。"},{"e":"象形。","n":"象㒳㒳竝生。陟玉切。三部。"}]},"万":{"expl":"蟲也。从厹，象形。","rad":"禸","fanqie":"無販切","vol":"14","duan":[{"e":"蟲也。","n":"謂蟲名也。叚借爲十千數名。而十千無正字。遂久叚不歸。學者昧其本義矣。唐人十千作万。故廣韵万與萬別。"},{"e":"从厹。","n":"葢其蟲四足像獸。"}]},"海":{"expl":"天池也。以納百川者。从水每聲。","rad":"水","fanqie":"呼改切","vol":"11","duan":[{"e":"天池也。","n":"見莊子消搖游。"},{"e":"㠯納百川者。","n":"爾雅。九夷、八狄、七戎、六蠻、謂之四海。此引伸之義也。凡地大物博者、皆得謂之海。"}]},"段":{"expl":"椎物也。从殳，耑省聲。","rad":"殳","fanqie":"徒玩切","vol":"03","duan":[{"e":"椎物也。","n":"周椎曰椎。考工記。段氏爲鎛器。徐丁亂反。劉徒亂反。徐音是也。鎛欲其段之堅。故官曰段氏。函人職曰。凡甲鍛不摰則不堅。鍛亦當作段。金部曰。鍛、小冶也。小冶、小鑄之竈也。後人以鍛爲段字。以段爲分段字。讀徒亂切。分段字自應作𣃔。葢古今字之不同如此。大雅。取厲取碫。毛曰。碫、段石也。鄭曰。段石所以爲段質也。古本當如是。石部碫、段石也。從石段。春秋傳鄭公孫段、字子石。古本當如是。段石與厲石各物。說文訓詁多宗毛傳。"},{"e":"从殳。耑省聲。","n":"徒玩切。十四部。"}]},"皇":{"expl":"大也。从自。自，始也。始皇者，三皇，大君也。自，讀若鼻，今俗以始生子爲鼻子。","rad":"王","fanqie":"胡光切","vol":"01","duan":[{"e":"大也。","n":"見詩毛傳。"},{"e":"从自王。","n":"依韵㑹補王字"}]},"邓":{"expl":"曼姓之國。今屬南陽。从邑登聲。","rad":"邑","fanqie":"徒亙切","vol":"06","duan":[{"e":"曼姓之國。","n":"左傳。楚武王夫人曰鄧曼。則知鄧國曼姓也。前志曰。鄧縣故國。"},{"e":"今屬南陽。","n":"南陽郡鄧、二志周。今河南南陽府鄧州是其地。"}]},"锐":{"expl":"芒也。从金兌聲。","rad":"金","fanqie":"以芮切","vol":"14","duan":[{"e":"芒也。","n":"芒者、艸耑也。艸耑必鑯。故引申爲芒角字。今俗用鋒鋩字、古衹用夆芒。"},{"e":"从金。兌聲。","n":"以芮切。十五部。"}]},"承":{"expl":"奉也。受也。从手从卪从𠬞。","rad":"手","fanqie":"署陵切","vol":"12","duan":[{"e":"奉也。受也。","n":"？部曰。奉者、承也。是二篆爲轉注也。𠬪部曰。受者、相付也。凡言承受、承順、承繼、又魯頌傳曰承止也皆奉之訓也。凡言或承之羞、承之以劒皆相付之訓也。左傳曰。蔡大夫恐昭矦之又遷也。承。此叚承爲懲也。"},{"e":"从手卪𠬞。","n":"合三字會意。署陵切。六部。"}]},"梁":{"expl":"水橋也。从木从水，刅聲。","rad":"木","fanqie":"呂張切","vol":"06","duan":[{"e":"水橋也。","n":"梁之字用木跨水、則今之橋也。孟子。十一月輿梁成古本如是國語引夏令曰。九月除道。十月成梁。大雅。造舟爲梁。皆今之橋制。見於經傳者、言梁不言橋也。若爾雅。隄謂之梁。毛傳。石絶水曰梁。謂所以偃塞取魚者。亦取亙於水中之義謂之梁。凡毛詩自造舟爲梁外。多言魚梁。"},{"e":"從木水。","n":"會意。"}]},"君":{"expl":"尊也。从尹。發號，故从口。","rad":"口","fanqie":"舉云切","vol":"02","duan":[{"e":"尊也。","n":"此羊祥也、門聞也、戶護也、髮拔也之例。"},{"e":"从尹口。","n":"尹、治也。"}]},"铃":{"expl":"令丁也。从金从令，令亦聲。","rad":"金","fanqie":"郎丁切","vol":"14","duan":[{"e":"令丁也。","n":"令平聲。令丁㬪韵字。晉語十一注。丁寧、令丁。謂鉦也。吳語十九。丁寧、令丁。謂鉦也。今國語皆奪令丁字。而存於舊音補音。廣韵曰。鈴似鐘而小。然則鐲鈴一物也。古謂之丁寧。漢謂之令丁。在旂上者亦曰鈴。"},{"e":"从金。令聲。","n":"郎丁切。古音在十二部"}]},"杨":{"expl":"木也。从木昜聲。","rad":"木","fanqie":"与章切","vol":"06","duan":[{"e":"蒲桺也。","n":"各木作木也二字。今依藝文類聚、初學記、本艸圖經、太平御覽所引正。釋木云。楊蒲桺。許所本也。按蒲。葢本作浦。浦、水瀕也。王風。不流束蒲。毛云。蒲艸也。箋云。蒲、蒲桺。孫毓云。蒲艸之聲不與戎許相協。箋義爲長。是則晉人讀蒲桺爲浦桺之明證。古今注曰。蒲桺生水邊。又曰。水楊、蒲楊也。枝勁細。任矢用。任矢用者、左傳云董澤之蒲是也。絫呼曰蒲桺。單𧦝曰蒲。音同浦。至唐而失其讀矣。"},{"e":"從木。昜聲。","n":"与章切。十部。古假楊爲揚。故詩楊之水。毛曰。楊、激揚也。廣雅曰。楊、揚也。佩觽曰。楊、桺也。亦州名。古書州名皆作楊矣。"}]},"晞":{"expl":"乾也。从日希聲。","rad":"日","fanqie":"香衣切","vol":"07","duan":[{"e":"乾也。","n":"玄應書引作日乾曰晞。小雅。湛湛露斯。匪陽不晞。傳曰。陽、日也。晞、乾也。陽日也者、謂陽卽暘之叚借也。方言。膊曬晞㬥也。㬥五穀之類。秦晉之閒謂之曬。東齋北燕海岱之郊謂之晞。又曰。晞、燥也。"},{"e":"从日。希聲。","n":"香衣切。十五部。"}]},"邱":{"expl":"地名。从邑丘聲。","rad":"邑","fanqie":"去鳩切","vol":"06","duan":[{"e":"地名。从邑。丠聲。","n":"去鳩切。古音在一部。今制、諱孔子名之字曰邱。"}]},"霏":{"expl":"雨雲皃。从雨非聲。","rad":"雨","fanqie":"芳非切","vol":"11","duan":[]},"方":{"expl":"併船也。象兩舟省、緫頭形。凡方之屬皆从方。","rad":"方","fanqie":"府良切","vol":"08","duan":[{"e":"倂船也。","n":"周南。不可方思。邶風。方之舟之。釋言及毛傳皆曰。方、泭也。今爾雅改方爲舫。非其義矣。倂船者、並兩船爲一。釋水曰。大夫方舟。謂倂兩船也。泭者、編木以爲渡。與倂船異事。何以毛公釋方、不曰倂船而曰泭也。曰倂船、編木其用略同。故俱得名方。方舟爲大夫之禮。詩所言不必大夫。則釋以泭可矣。若許說字。則見下从舟省而上有竝頭之象。故知倂船爲本義。編木爲引伸之義。又引伸之爲比方。子貢方人是也。秦風。西夫之防。毛曰。防、比也。謂防卽方之假借也。又引伸之爲方圓、爲方正、爲方向。又假借爲旁。丄部曰。旁、溥也。凡今文尙書作旁者、古文尙書作方。爲大也。生民。實方實苞。毛曰。方、極畝也。極畝、大之意也。又假借爲甫。召南。維鳩方之。毛曰。方之、方有之也。方有之猶甫有之也。"},{"e":"象兩舟省總頭形。","n":"兩當作㒳。下象兩舟倂爲一。上象兩船頭總於一處也。府良切。十部。通俗文。連舟曰舫。與許說字不同。葢方正字俗用舫。"}]},"梓":{"expl":"楸也。从木，宰省聲。","rad":"木","fanqie":"卽里切","vol":"06","duan":[{"e":"楸也。從木。宰省聲。","n":"卽裏切。一部。按許知宰省聲而非辛聲者、於或字知之也。或字、葢古文遺與。"}]},"吴":{"expl":"姓也。亦郡也。一曰吳，大言也。从夨、口。","rad":"夨","fanqie":"五乎切","vol":"10","duan":[{"e":"大言也。","n":"大言之上各本有姓也亦郡也一曰吳八字。乃妄人所增。今𠜂正。檢韵會本正如是。周頌絲衣、魯頌泮水皆曰不吳。傳箋皆云吳、譁也。言部曰。譁者、讙也。然則大言卽謂譁也。孔沖遠詩正義作不娛。史記孝武本紀作不虞。皆叚借字。大言者、吳字之本義也。引伸之爲凡大之偁。方言曰。吳、大也。九章。齊吳榜以擊汏。王注。齊舉大櫂。"},{"e":"从夨口。","n":"大言非正理也。故从夨口。五乎切。五部。何承天改吳作㕦。音胡化反。其繆甚矣。"}]},"端":{"expl":"直也。从立耑聲。","rad":"立","fanqie":"多官切","vol":"10","duan":[{"e":"直也。","n":"用爲發耑、耑緒字者叚借也。"},{"e":"从立。耑聲。","n":"多官切。十四部。"}]},"微":{"expl":"隱行也。从彳𢼸聲。《春秋傳》曰：“白公其徒微之。”","rad":"彳","fanqie":"無非切","vol":"02","duan":[{"e":"隱行也。","n":"𢼸訓眇。微从彳、訓隱行。叚借通用微而？不行。邶風。微我無酒。又假微爲非。"},{"e":"从彳。𢼸聲。","n":"無非切。十五部。"}]},"丁":{"expl":"夏時萬物皆丁實。象形。丁承丙，象人心。凡丁之屬皆从丁。","rad":"丁","fanqie":"當經切","vol":"14","duan":[{"e":"夏時萬物皆丁實。","n":"丁實小徐本作丁壯成實。律書曰。丁者、言萬物之丁壯也。律曆志曰。大盛於丁。鄭注月令曰。時萬物皆強大。"},{"e":"象形。","n":"當經切。十一部。"}]},"怡":{"expl":"和也。从心台聲。","rad":"心","fanqie":"與之切","vol":"10","duan":[{"e":"龢也。","n":"各本作和。今正。龢者、調也。玉篇曰。怡者、悅也。樂也。古多叚台字。禹貢。祗台德先。鄭注云。敬和。"},{"e":"从心。台聲。","n":"與之切。一部。"}]},"萱":{"expl":"令人忘憂艸也。从艸憲聲。《詩》曰：“安得藼艸？”","rad":"艸","fanqie":"況袁切","vol":"01","duan":[{"e":"令人忘憂之艸也。","n":"見毛傳。藼之言諼也。諼、忘也。"},{"e":"从艸。憲聲。","n":"況袁切。十四部。"}]},"江":{"expl":"水。出蜀湔氐徼外崏山，入海。从水工聲。","rad":"水","fanqie":"古雙切","vol":"11","duan":[{"e":"江水。出蜀湔氏徼外崏山。入海。","n":"蜀郡湔氐道、二志同。前志曰。湔氐道、禹貢崏山𡉈西徼外。江水所出。東南至江都入海。過郡九。行七千二百六十里。今本九作七。行七千作行二千。今依徐鍇所引正。過郡九者、蜀郡、犍爲、巴郡、南郡、長沙、江夏、廬江、丹陽、廣陵國也。湔氐徼外崏山、卽禹貢岷山。封禪書謂之瀆山。李膺益州記詞之羊膊嶺。今四川龍安府松潘㕔卽松潘衞衞北二百三十里大分水嶺是也。流經茂州、成都府、眉州、嘉定府、敘州府、瀘州、重慶府、忠州、夔州府、湖廣之宜昌府、荆州府、岳州府、武昌府、漢陽府、黃州府、江西之九江府、江南之安慶府、池州府、太平府、江甯府、鎭江府、常州府諸境。至北岸通州、南岸蘇州府昭文縣境入海。此禹貢漢志所謂北江入海也。"},{"e":"从水。工聲。","n":"古雙切。九部。"}]},"秦":{"expl":"伯益之後所封國。地宜禾。从禾，舂省。一曰秦，禾名。","rad":"禾","fanqie":"匠鄰切","vol":"07","duan":[{"e":"伯益之後所封國。","n":"鄭詩諩曰。秦者、隴西谷名。於禹貢近雍州鳥鼠之山。堯時有伯翳者。實臯陶之子。佐禹治水。水土旣平。舜命作虞官。掌上下草木鳥獸。賜姓曰嬴。歷夏商興衰。亦世有人焉。周孝王使其末孫非子養馬於汧渭之間。孝王封非子爲附庸。邑之於秦谷。至曾孫秦仲。宣王又命作大夫。始有車馬禮樂侍御之好。國人美之。秦之變風始作。按伯益、伯翳實一人。臯陶之子也。今甘肅秦州淸水縣有故秦城。漢地理志之隴西秦亭、秦谷也。"},{"e":"地宜禾。从禾、舂省。","n":"地宜禾者、說字形所以从禾从舂也。職方氏曰。雍州穀宜黍稷。豈秦穀獨宜禾與。匠鄰切。十二部。按此字不以舂禾會意爲本義、以地名爲本義者、通人所傳如是也。"}]},"谷":{"expl":"泉出通川爲谷。从水半見，出於口。凡谷之屬皆从谷。","rad":"谷","fanqie":"古禄切","vol":"11","duan":[]},"洛":{"expl":"水。出左馮翊歸德北夷界中，東南入渭。从水各聲。","rad":"水","fanqie":"盧各切","vol":"11","duan":[{"e":"洛水。出左馮翊歸德北夷畍中。東南入渭。","n":"左馮翊三字、當作北地二字。前志北地郡歸德下。洛水出北蠻夷中。入河。入河者、入渭以入河也。此揔舉其源委也。左馮翊褱德下曰。洛水東南入渭。此言其入渭之處也。許之例。舉源地、不舉委地。然則當云出北地歸德無疑矣。今甘肅慶陽府安化合水二縣、漢歸德地也。今陝西同州府朝邑縣有懷德城、漢縣也。括地志云。洛水源出慶州洛源縣白於山。方輿紀要曰。洛水出慶陽府合水縣北二十里白於山。東北流經廢洛源縣。又經保安縣、安塞縣、甘泉縣、鄜州。又南經洛川縣南、中部縣東、而沮水入焉。沮水自中部縣子午嶺東南流而入於洛水。卽說文𣻐水、出北地直路西、東入洛也。自是洛水亦兼沮水之稱。又南流經宜君縣。過耀州。合漆水。歷三原縣、富平縣、白水縣。又東南流經澄城縣、同州府。至朝邑縣南入渭水。水道提綱云。舊合渭入河。自明時改流。徑入河。不南入渭。今洛口南去渭口三十里。按水經注本有雍州洛水篇。今亡之矣。禹貢道渭節謂之漆沮。職方雍州其浸渭洛。小雅瞻"},{"e":"从水。各聲。","n":"盧各切。五部。按雍州洛水。豫州雒水。其字分別。自古不紊。周禮職方。豫州、其川熒雒。雍州、其浸渭洛。（正義本不誤）逸周書職方解、地理志引職方正同。雒不見於詩。瞻彼洛矣傳曰。洛、宗周浸水也。此職方氏文也。洛不見於左傳。傳凡雒字皆作雒。如僖七年伊雒之戎、宣三年楚子伐陸渾之戎遂至於雒是也。淮南墬形訓曰。洛出獵山。據高注謂雍州水也。雒出熊耳。據高注謂豫州水也。漢地理志弘農上雒下云。禹貢雒水、出冢領山。東北至鞏入河。豫州川。盧氏下云。伊水、出熊耳山。東北入雒。黽池下云。穀水、出[穀陽谷。東北至穀城入雒。新安下云。禹貢澗水、在東南入雒。河南穀成下云。禹貢廛水、出朁亭北。東南入雒。此謂豫州水也。左馮翊褱德下云。洛水、東南入渭。北地歸德下云。洛水、出北蠻夷中。入河。直路下云。沮水、出東西入洛。此謂雍州水也。已上皆經數千年尙未誤者。而許書水部下不舉豫州水。尤爲二字分別之證。後人書豫水作洛。其誤起於魏。裴松之引"}]},"俟":{"expl":"大也。从人矣聲。《詩》曰：“伾伾俟俟。”","rad":"人","fanqie":"牀史切","vol":"08","duan":[{"e":"大也。","n":"此俟之本義也。自經傳假爲竢字。而俟之本義廢矣。立部曰。竢、待也。廢竢而用俟。則竢俟爲古今字矣。"},{"e":"从人。矣聲。","n":"牀史切。一部。"}]},"依":{"expl":"倚也。从人衣聲。","rad":"人","fanqie":"於稀切","vol":"08","duan":[{"e":"倚也。从人。衣聲。","n":"於稀切。十五部。"}]},"森":{"expl":"木多皃。从林从木。讀若曾參之參。","rad":"林","fanqie":"所今切","vol":"06","duan":[{"e":"木多皃。從林。從木。","n":"按篇、韵皆云。森、長木皃。疑篇、韵所據爲長。從林從木正謂有木出平林之上也。"},{"e":"讀若曾參之參。","n":"所今切。七部。"}]},"义":{"expl":"己之威儀也。從我、羊。","rad":"我","fanqie":"宜寄切","vol":"12","duan":[{"e":"己之威義也。","n":"言己者、以字之从我也。己、中宮。象人腹。故謂身曰己。義各本作儀。今正。古者威儀字作義。今仁義字用之。儀者、度也。今威儀字用之。誼者、人所宜也。今情誼字用之。鄭司農注周禮肆師。古者書儀但爲義。今時所謂義爲誼。是謂義爲古文威儀字。誼爲古文仁義字。故許各仍古訓。而訓儀爲度。凡儀象、儀匹、引申於此。非威儀字也。古經轉寫旣久。肴襍難辨。據鄭、許之言可以知其意。威義古分言之者、如北宮文子云有威而可畏謂之威、有儀而可象謂之義、詩言令義令色、無非無義是也。威義連文不分者、則隨處而是。但今無不作儀矣。毛詩。威義棣棣。不可選也。傳曰。君子望之儼然可畏。禮容俯仰各有宜耳。棣棣、富而閒習也。不可選、物有其容不可數也。義之本訓謂禮容各得其宜。禮容得宜則善矣。故文王、我將毛傳皆曰。義、善也。引申之訓也。"},{"e":"从我。从羊。","n":"威儀岀於己、故从我。董子曰。仁者、人也。義者、我也。謂仁必及人。義必由中𣃔制也。从羊者、與善美同意。宜寄切。古音在十七部。"}]},"柏":{"expl":"鞠也。从木白聲。","rad":"木","fanqie":"博陌切","vol":"06","duan":[{"e":"鞠也。","n":"釋木曰。柏、椈襍記。暢臼以椈。鄭曰。椈、柏也。按椈者鞠之俗。柏、古多假借爲伯仲之伯、促迫之迫。"},{"e":"從木。白聲。","n":"博陌切。古音在五部。張參曰。經典相承亦作栢。"}]},"然":{"expl":"燒也。从火肰聲。","rad":"火","fanqie":"如延切","vol":"10","duan":[{"e":"燒也。","n":"通叚爲語䛐。訓爲如此。爾之轉語也。"},{"e":"从火。肰聲。","n":"如延切。十四部。俗作燃。非是。"}]},"湘":{"expl":"水。出零陵陽海山，北入江。从水相聲。","rad":"水","fanqie":"息良切","vol":"11","duan":[{"e":"湘水。出零陵縣陽海山。北入江。","n":"縣字今補。凡郡縣同名、則言縣以該之也。零陵郡零陵、二志同。前志零陵下曰。陽海山、湘水所出。北至酃入江。過郡二。行二千五百三十里。過郡二者、零陵長沙也。又有離水。東南至廣信入鬱。（下衍林字非）行九百八十里。水經曰。湘水、出零陵始安縣陽海山。東北流過下雋縣西。又北至巴丘山。入於江。酈曰。陽海山卽陽朔山。山在始安縣北。縣故零陵之南部也。湘灕同源。南爲灕水。北則湘川。今廣西桂林府與安縣南九十里。俗謂之海陽山、卽陽海山也。湘水出焉。北流經全州入湖南畍。經東安縣、零陵縣、祁陽縣、常寧縣、衡陽縣、衡山縣、湘潭縣、善化縣。至喬口。資水來會。又經湘陰縣。至磊石山分爲二派。又合入洞庭湖曰湘口。漢志云至酃入江。未詳。按離水字本不從水旁。後人益之耳。許書所無。"},{"e":"从水。相聲。","n":"息良切。十部。按詩召南于以湘之。假借爲鬺字。"}]},"淑":{"expl":"清湛也。从水叔聲。","rad":"水","fanqie":"殊六切","vol":"11","duan":[{"e":"淸湛也。","n":"湛、𣳚也。湛沈古今字。今俗云深沈是也。釋詁曰。淑善也。此引伸之義。"},{"e":"从水。叔聲。","n":"殊六切。三部。"}]},"刘":{"expl":"殺也。","rad":"金","fanqie":"力求切","vol":"14","duan":[]},"跋":{"expl":"蹎跋也。从足犮聲。","rad":"足","fanqie":"北末切","vol":"02","duan":[{"e":"蹎也。","n":"依豳風正義訂。跋、經傳多叚借沛字爲之。大雅、論語顚沛皆卽蹎跋也。毛傳。顚、仆也。沛、拔也。拔同跋。豳風狼跋亦或作拔。馬融論語注曰。顚沛、僵仆也。按豳風狼跋其胡謂？也。？則仆矣。引伸爲近人題跋字。題者標其前。跋者系其後也。邶風傳。艸行曰跋。別一義。"},{"e":"从足。犮聲。","n":"北末切。廣韵蒲撥切。十五部。"}]},"戴":{"expl":"分物得增益曰戴。从異𢦔聲。","rad":"異","fanqie":"都代切","vol":"03","duan":[{"e":"分物得增益曰戴。","n":"釋訓曰。蓁蓁、孽孽、戴也。毛傳云。蓁蓁、至盛皃。孽孽、盛飾。是皆謂加多也。引伸之凡加於上皆曰戴。如土山戴石曰崔嵬、石山戴土曰？是也。又與載通用。言其上曰戴。言其下曰載也。釋山或本。石載土謂之崔嵬。土載石爲砠。謂石載於土、土載於石則與毛傳不異也。周頌載弁俅俅、月令載青旗皆同戴。"},{"e":"从異。𢦒聲。","n":"都代切。一部。"}]},"萌":{"expl":"艸芽也。从艸明聲。","rad":"艸","fanqie":"武庚切","vol":"01","duan":[{"e":"艸木芽也。","n":"木字依玉篇補。說文以艸木芽、艸木榦、艸木葉聮綴成文。？芽析言則有別。尚書大傳。周以至動、殷以萌、夏以牙是也。統言則不別。故曰？、艸木芽也。月令。句者畢出。？者盡達。注。句、屈生者。𦬆而直曰？。樂記作區？。"},{"e":"从艸。朙聲。","n":"武庚切。古音在十部。"}]},"噬":{"expl":"啗也。喙也。从口筮聲。","rad":"口","fanqie":"時制切","vol":"02","duan":[]},"熊":{"expl":"獸似豕。山居，冬蟄。从能，炎省聲。凡熊之屬皆从熊。","rad":"熊","fanqie":"羽弓切","vol":"10","duan":[{"e":"熊獸、佀豕。山凥。","n":"俗作居。"},{"e":"冬蟄。","n":"見夏小正。"}]},"钱":{"expl":"銚也。古田器。从金戔聲。《詩》曰：“庤乃錢鎛。”","rad":"金","fanqie":"即淺切","vol":"14","duan":[{"e":"銚也。古者田器。","n":"詩毛傳云尒。見上文銚字下。云古田器者、古謂之錢。今則但謂之銚、謂之臿。不謂之錢。而錢以爲貨泉之名。"},{"e":"从金。戔聲。詩曰。庤乃錢鎛。","n":"周頌臣工文。卽淺切。十四部。"}]},"靖":{"expl":"立竫也。从立青聲。一曰細皃。","rad":"立","fanqie":"疾郢切","vol":"10","duan":[{"e":"立竫也。","n":"謂立容安竫也。安而後能慮。故釋詁、毛傳皆曰靖、謀也。"},{"e":"从立。靑聲。","n":"疾郢切。十一部。"}]},"陶":{"expl":"再成丘也，在濟陰。从𨸏匋聲。《夏書》曰：“東至于陶丘。”陶丘有堯城，堯嘗所居，故堯號陶唐氏。","rad":"𨸏","fanqie":"徒刀切","vol":"14","duan":[{"e":"再成丘也。在濟陰。","n":"釋丘曰。一成爲敦丘。再成爲陶丘。禹貢曰。道沇水東流爲濟。入于河。泆爲熒。東出于陶丘北。地理志曰。濟陰郡定陶縣。禹貢陶丘在西南。按定陶故城在今山東曹州府定陶縣西南。古陶丘在焉。"},{"e":"从𨸏。匋聲。","n":"徒刀切。古音在三部。"}]},"安":{"expl":"靜也。从女在宀下。","rad":"宀","fanqie":"烏寒切","vol":"07","duan":[{"e":"竫也。","n":"竫各本作靜。今正。立部曰。竫者、亭安也。與此爲轉注。靑部靜者、審也。非其義。方言曰。安、靜也。以許書律之。叚靜爲竫耳。安亦用爲語詞。"},{"e":"从女在宀中。","n":"此與寍同意。烏寒切。十四部。"}]},"过":{"expl":"度也。从辵咼聲。","rad":"辵","fanqie":"古禾切","vol":"02","duan":[{"e":"度也。","n":"引伸爲有過之過。釋言。郵過也。謂郵亭是人所過。愆郵是人之過。皆是。分別平去聲者、俗說也。"},{"e":"从辵。咼聲。","n":"古禾切。十七部。"}]},"熙":{"expl":"燥也。从火巸聲。","rad":"火","fanqie":"許其切","vol":"10","duan":[{"e":"燥也。","n":"文𨕖劉琨贈盧諶詩注引此。下有謂㬥燥也四字。蓋庾儼黙注語。釋詁又曰。熙、興也。周語叔向釋昊天有成命之詩曰。緝、明。熙、廣也。毛傳本之。箋據釋詁熙、光也。云廣當爲光。按文王傳曰。緝熙、光明也。敬之傳曰。光、廣也。是古光廣義通。燥者、熙之本義。又訓興、訓光者、引申之義也。"},{"e":"从火。巸聲。","n":"巸見𦣞部。許其切。一部。"}]},"沈":{"expl":"陵上滈水也。从水冘聲。一曰濁黕也。","rad":"水","fanqie":"直深切","vol":"11","duan":[{"e":"陵上滈水也。","n":"謂陵上雨積停潦也。古多假借爲湛𣳚之湛。如小雅載沈載浮是。又或借爲瀋字。檀弓爲榆沈是也。"},{"e":"从水。冘聲。","n":"直深切。又尸甚切。八部。"}]},"袁":{"expl":"長衣皃。从衣，叀省聲。","rad":"衣","fanqie":"羽元切","vol":"08","duan":[{"e":"長衣皃。","n":"此字之本義。今衹謂爲姓。而本義廢矣。古與爰通用。如袁盎、漢書作爰盎是也。王風。有兔爰爰。傳曰。爰爰、緩意。遠轅等字以袁爲聲。亦取其意也。"},{"e":"从衣。叀省聲。","n":"葢从古文叀而省。羽元切。十四部。"}]},"沁":{"expl":"水。出上黨羊頭山，東南入河。从水心聲。","rad":"水","fanqie":"七鴆切","vol":"11","duan":[{"e":"沁水。出上黨穀遠羊頭山。東南入河。","n":"上黨郡穀遠、二志同。今山西沁洲沁源縣縣城南故穀遠城、漢縣也。前志穀遠下曰。羊頭山世靡谷。沁水所出。東南至熒陽入河。過郡三。行九百七十里。三郡、上黨河內河南也。水經曰。沁水出上黨涅縣謁戾山。南過穀遠縣東。至熒陽縣北。東入於河。按水經及注皆云至熒陽入河。師古據唐時在懷州武陟入河。疑轉寫錯誤。非也。古水道與唐時不同耳。山海經水經舉涅謁戾山、班許舉穀遠羊頭山者、羊頭卽謁戾也。戴先生曰。山在今武鄉縣西百二十里。西北接祁縣平遙縣。西南接沁源縣。一名麓臺山。迆邐而西爲綿山。其北爲介休縣。西爲靈石縣。皆謁戾山也。今沁水出沁州沁源縣西北百里之綿山東谷。西南流經平陽府岳陽縣東。又折而東南經澤州府沁水縣東。又南經陽城縣東而入河南懷慶府畍。歷濟源縣東北。又南經府城北。又東南經武陟縣東、修琥縣西而入於河。與唐時入河處同。"},{"e":"从水。心聲。","n":"七鴆切。七部。經典釋文引郭樸三蒼解詁曰。音狗吣之吣。吣今譌作沁。"}]},"呼":{"expl":"外息也。从口乎聲。","rad":"口","fanqie":"荒烏切","vol":"02","duan":[{"e":"外息也。","n":"外息、出其息也。"},{"e":"从口。乎聲。","n":"荒烏切。五部。今人用此爲號嘑、𧦝召字。非也。"}]},"宇":{"expl":"屋邊也。从宀于聲。《易》曰：“上棟下宇。”","rad":"宀","fanqie":"王榘切","vol":"07","duan":[{"e":"屋邊也。","n":"幽風。八月在宇。陸德明曰。屋四垂爲宇。引韓詩宇、屋𩅸也。高誘注淮南曰。宇、屋簷也。引伸之凡邊謂之宇。如輪人爲葢上欲尊而宇欲卑、左傳云在君之字下、又云失其守宇皆是也。宇者、言其邊。故引伸之義又爲大。文子及三蒼云。上下四方謂之宇。往古來今謂之宙。上下四方者、大之所際也。莊子云。有實而無乎處者、宇也。有長而無本剽者、宙也。有實而無乎處、謂四方上下實有所際。而所際之處不可得到。"},{"e":"从宀。亏聲。","n":"王榘切。五部。"}]},"阳":{"expl":"高、明也。从𨸏昜聲。","rad":"𨸏","fanqie":"與章切","vol":"14","duan":[{"e":"高朙也。","n":"闇之反也。"},{"e":"从𨸏。","n":"不言山南曰昜者、陰之解可錯見也。山南曰陽、故从𨸏。毛傳曰。山東曰朝陽。山西曰夕陽。"}]},"雷":{"expl":"陰陽薄動靁雨，生物者也。从雨，畾象回轉形。","rad":"雨","fanqie":"魯回切","vol":"11","duan":[{"e":"𩃬昜薄動生物者也。","n":"各本作陰陽。今正。動下各本有靁雨二字。不辭。今依韵會本正。薄音博。迫也。陰陽迫動、卽謂靁也。迫動下文所謂回轉也。所以回生萬物者也。"},{"e":"从雨。畾象回轉形。","n":"許書有畕無畾。凡積三則爲衆。衆則盛。盛則必回轉。二月陽盛。靁發聲。故以畾象其回轉之形。非三田也。韵書有畾字、訓田閒。誤矣。凡許書字有畾聲者、皆當云靁省聲也。魯回切。十五部。○凡古器多以回爲靁。"}]},"人":{"expl":"天地之性最貴者也。此籒文。象臂脛之形。凡人之屬皆从人。","rad":"人","fanqie":"如鄰切","vol":"08","duan":[{"e":"天地之性冣貴者也。","n":"冣本作最。性古文以爲生字。左傳。正德利用厚生。國語作厚性是也。許偁古語不改其字。禮運曰。人者、其天地之德。陰陽之交。鬼神之會。五行之秀氣也。又曰。人者、天地之心也。五行之端也。食味別聲被色而生者也。按禽獸艸木皆天地所生。而不得爲天地之心。惟人爲天地之心。故天地之生此爲極貴。天地之心謂之人。能與天地合德。果實之心亦謂之人。能復生艸木而成果實。皆至微而具全體也。果人之字、自宋元以前本艸方書詩歌紀載無不作人字。自明成化重刊本艸乃盡改爲仁字。於理不通。學者所當知也。○仁者、人之德也。不可謂人曰仁。其可謂果人曰果仁哉。金泰和閒所刊本艸皆作人。藏袁廷檮所。"},{"e":"此籒文。","n":"此對儿爲古文奇字人言之。如大之有古文籒文之別也。字多从籒文者。故先籒而後古文。"}]},"洋":{"expl":"水。出齊臨朐高山，東北入鉅定。从水羊聲。","rad":"水","fanqie":"似羊切","vol":"11","duan":[{"e":"𣴱水。出齊臨胊高山。東北入鉅定。","n":"齊郡臨胊、後志作齊國臨胊。今山東靑州府臨胊縣其地也。前志臨胊下曰。石膏山、洋水所出。東北至廣饒入鉅定。水經注巨洋水篇曰。巨洋水、又逕臨胊縣故城東。又東北逕委粟山。又東北、洋水注之。水西出石膏山西北石澗口。東南逕逢山祠西。又東南歴逢山下。卽石膏山也。巨洋水、又東北逕劇縣故城西。又東北逕益縣故城東。又東北積而爲潭。枝津出焉。謂之百尺溝。西北流注於巨淀。又東北逕壽光縣故城西。又東北注於海。按班、許曰洋水。卽水經及注之巨洋水也。班、許以出臨胊石膏山者爲正源耳。許云高山、卽石膏山也。前志齊郡有廣饒、鉅定二縣。馬車瀆水首受鉅定。然則鉅定本水名。因以爲縣名。定淀古今字。魏都賦張注曰淀者、如淵而淺是也。廣饒、鉅定故城皆在今山東靑州府樂安縣境。今樂安縣東北四十里淸水泊、卽古鉅定湖。巨洋水今曰瀰河。源出今臨朐縣南沂山西麓。北流逕臨朐縣東。又北歴益都縣。又東北流逕壽光東。又東北會黑塚泊。入於海。今南陽水亦名長沙"},{"e":"从水。芉聲。","n":"似羊切。十部。按毛詩衞風傳曰。洋洋、盛大也。魯頌傳曰。洋洋、衆多也。讀與章切。"}]},"木":{"expl":"冒也。冒地而生。東方之行。从屮，下象其根。凡木之屬皆从木。","rad":"木","fanqie":"莫卜切","vol":"06","duan":[{"e":"冒也.","n":"以疊韵爲訓。冃部曰。冢{冡}而前也。"},{"e":"冒地而生。東方之行。从屮。下象其根。","n":"謂<>也。屮象上出。<>象下垂。莫卜切。三部。"}]},"伊":{"expl":"殷聖人阿衡，尹治天下者。从人从尹。","rad":"人","fanqie":"於脂切","vol":"08","duan":[{"e":"殷聖人阿衡也。","n":"殷聖人之上當有伊尹二字。傳寫奪之。阿衡見商頌。毛傳曰。阿衡、伊尹也。箋云。阿倚、衡平也。伊尹、湯所依倚而取平。故以爲官名。伊與阿、尹與衡皆雙聲。然則一語之轉也。許云伊尹、殷聖人阿衡也。本毛說。不言伊尹爲姓名也。諸家或云伊氏尹字。或云名摯。皆所傳聞異辭耳。禮記所偁古文尙書㒳言尹躬。則尹實其名。"},{"e":"尹治天下者。从人尹。","n":"尹治猶言治平。此說从人尹之意也。言阿衡者。尹治天下者也。故又謂之伊尹。而伊字亦从尹。於脂切。十五部。釋詁、毛傳皆曰。伊、維也。爲發語辭。詩雄雉、蒹葭、東山、白駒之伊字鄭箋云。當爲繄。繄猶是也。"}]},"公":{"expl":"平分也。从八从厶。(音司。)八猶背也。韓非曰：背厶爲公。","rad":"八","fanqie":"古紅切","vol":"02","duan":[{"e":"平分也。从八厶。","n":"八厶、背私也。今本从八从厶。凡此等从字皆淺人所增。"},{"e":"八猶背也。","n":"鄭注堯典分北三苗云。北猶別也。證以韋昭吳語注云。北古之背字。然則許鄭之語正互相發明。分別之乃相僢背。其義相因相足。故許不云八、背也。而云猶背。鄭不云北、別也。而云猶別。凡古訓故之言猶者視此。古紅切。九部。"}]},"黄":{"expl":"地之色也。从田从炗，炗亦聲。炗，古文光。凡黃之屬皆从黃。","rad":"黃","fanqie":"乎光切","vol":"13","duan":[{"e":"地之色也。","n":"玄者、幽遠也。則爲天之色可知。易曰。夫玄黃者、天地之襍也。天玄而地黃。"},{"e":"从田。","n":"土色黃。故从田。"}]},"独":{"expl":"犬相得而鬬也。从犬蜀聲。羊爲羣，犬爲獨也。一曰北嚻山有獨𤞞獸，如虎，白身，豕鬣，尾如馬。","rad":"犬","fanqie":"徒谷切","vol":"10","duan":[{"e":"犬相得而鬥也。","n":"鬥各本作鬬。今正。凡爭鬥字許作鬥。鬬者、遇也。其義各殊。今人乃謂鬬正、鬥俗。非也。"},{"e":"从犬。蜀聲。","n":"徒谷切。三部。"}]},"石":{"expl":"山石也。在厂之下；囗，象形。凡石之屬皆从石。","rad":"石","fanqie":"常隻切","vol":"09","duan":[{"e":"山石也。","n":"或借爲碩大字。或借爲䄷字。䄷、百二十斤也。"},{"e":"在厂之下。囗象形。","n":"常隻切。古音在五部。"}]},"生":{"expl":"進也。象艸木生出土上。凡生之屬皆从生。","rad":"生","fanqie":"所庚切","vol":"06","duan":[{"e":"進也。象艸木生出土上。","n":"下象土。上象出。此與𡳿出𣎵以類相從。所庚切。十一部。"}]},"谢":{"expl":"辤去也。从言䠶聲。","rad":"言","fanqie":"辤夜切","vol":"03","duan":[{"e":"辤去也。","n":"辤、不受也。曲禮。大夫七十而致事。若不得謝。則必賜之几杖。此謝之本義也。引伸爲凡去之偁。又爲衰退之偁。俗謂拜賜曰謝。"},{"e":"从言。䠶聲。","n":"辤夜切。古音在五部。按經典無榭字。衹作謝。釋宫。無室曰榭。轉寫俗字也。木部不錄。"}]},"史":{"expl":"記事者也。从又持中。中，正也。凡史之屬皆从史。","rad":"史","fanqie":"疏士切","vol":"03","duan":[{"e":"記事者也。","n":"玉藻。動則左史書之。言則右史書之。不云記言者、以記事包之也。"},{"e":"从又持中。中、正也。","n":"君舉必書。良史書法不隱。疏士切。一部。"}]},"泓":{"expl":"下深皃。从水弘聲。","rad":"水","fanqie":"烏宏切","vol":"11","duan":[{"e":"下深貌。","n":"下深謂其上似淺陿、其下深廣也。楊子。其中宏深。其外肅括。月令。其器閎。鄭云。閎謂中寬。象土含物。泓之義略同。"},{"e":"从水。弘聲。","n":"烏宏切。古音在六部。"}]},"五":{"expl":"五行也。从二，陰陽在天地閒交午也。凡五之屬皆从五。","rad":"五","fanqie":"疑古切","vol":"14","duan":[{"e":"五行也。","n":"古之聖人知有水火木金土五者。而後造此字也。"},{"e":"从二。","n":"像天地。"}]},"长":{"expl":"久遠也。从兀从匕。兀者，高遠意也。久則變化。亾聲。纼者，倒亾也。凡長之屬皆从長。","rad":"長","fanqie":"直良切","vol":"09","duan":[{"e":"久遠也。","n":"久者、不暫也。遠者、不近也。引伸之爲滋長、長幼之長。今音知丈切。又爲多餘之。長、度長之長皆今音直亮切。兄下曰。長也。是滋長、長幼之長也。"},{"e":"从兀。从匕｛𠤎｝。","n":"會意。匕｛𠤎｝呼霸切。"}]},"傅":{"expl":"相也。从人尃聲。","rad":"人","fanqie":"方遇切","vol":"08","duan":[{"e":"相也。","n":"左傳。鄭伯傳王。注曰。傳、相也。賈子曰。傳、傳之德義。古假爲敷字。如禹敷土、亦作禹傳士是也。亦爲今之附近字。如凡言附箸是也。"},{"e":"从人。尃聲。","n":"方遇切。五部。"}]},"睿":{"expl":"深明也。通也。从𣦼从目，从谷省。","rad":"𣦼","fanqie":"以芮切","vol":"04","duan":[{"e":"𥥍明也。","n":"鉉本此下有通也二字。雖合古訓。然恐俗增。馬注尙書、鄭注尙書大傳皆曰。睿、通也。許則於叡曰深明也。於聖曰通也。叡從目、故曰明。聖從耳、故曰通。此許意也。周書謚法解曰。叡、聖也。邶風毛傳曰。聖、叡也。古文尙書睿作聖。故周書、毛傳叡聖互訓。楚語。謂之睿聖武公。韋曰。睿、明也。按韋但曰明、許曰深明者、許主解字。爲其字之從𣦼也。"},{"e":"从𣦼。从目。","n":"故曰深明。"}]},"铭":{"expl":"記也。从金名聲。","rad":"金","fanqie":"莫經切","vol":"14","duan":[]},"司":{"expl":"臣司事於外者。从反后。凡司之屬皆从司。","rad":"司","fanqie":"息兹切","vol":"09","duan":[{"e":"臣司事於外者。","n":"外對君而言。君在內也。臣宣力四方在外。故从反后。鄭風。邦之司直。傳曰。司、主也。凡主其事必伺察恐後。故古別無伺字。司卽伺字。見部曰。覹、司也。䙾、司人也。人部曰。伏、司也。𠊱司望也。頁部曰。䫔、司人也。㹜部曰。䫔、司也。豸下曰。欲有所司殺。皆卽今之伺字。周禮師氏、媒氏、禁殺戮之注皆云。司猶察也。俗又作覗。凡司其事者皆得曰有司。"},{"e":"从反后。","n":"惟反后乃鄉后矣。息茲切。一部。"}]}};
